function stripePlatformCard() {
  return '<div class="card" id="stripe-platform-card"><div class="task-sub">Loading Stripe platform setup…</div></div>';
}

async function wireStripePlatformCard() {
  const box = $('#stripe-platform-card');
  if (!box || !S.organizationId) return;
  const endpoint = `/api/organizations/${encodeURIComponent(S.organizationId)}/payments/stripe/platform`;
  let platform;
  try { platform = await api(endpoint); }
  catch (error) { box.innerHTML = `<p class="task-sub">${esc(error.message)}</p>`; return; }
  const status = platform.configured ? '<span class="chip" style="color:var(--ok,#4ec9a3)">Connect app ready</span>' : '<span class="chip">setup required</span>';
  const webhook = platform.webhookConfigured ? '<span class="chip" style="color:var(--ok,#4ec9a3)">webhook ready</span>' : '<span class="chip">webhook secret missing</span>';
  box.innerHTML = `<div class="section-h">Stripe Connect ${status} ${webhook}</div>
    <p class="task-sub">This application identifies the installation and receives callbacks. Organizations connect and fund their own Stripe accounts separately.</p>
    <p class="task-sub">Create or open the application in <a href="https://dashboard.stripe.com/settings/connect" target="_blank" rel="noopener">Stripe Dashboard</a>, then register the callback and webhook URLs below.</p>
    <div class="settings-grid">
      <label class="form-row">Connect client ID<input class="stripe-platform-client" value="${esc(platform.clientId || '')}" placeholder="ca_…" /></label>
      <label class="form-row">Platform secret key<input class="stripe-platform-secret" type="password" autocomplete="new-password" placeholder="${platform.secretKeyConfigured ? 'Configured — leave blank to keep' : 'sk_test_… or sk_live_…'}" /></label>
      <label class="form-row">Webhook signing secret<input class="stripe-platform-webhook-secret" type="password" autocomplete="new-password" placeholder="${platform.webhookConfigured ? 'Configured — leave blank to keep' : 'whsec_…'}" /></label>
      <label class="form-row">OAuth callback URL<input value="${esc(platform.callbackUrl)}" readonly /></label>
      <label class="form-row">Webhook destination URL<input value="${esc(platform.webhookUrl)}" readonly /></label>
    </div>
    <button class="btn sm primary stripe-platform-save">Save Stripe platform setup</button>
    ${platform.source === 'environment' ? '<p class="task-sub">Environment values currently supply this setup. Saved replacements use the encrypted vault and take precedence.</p>' : ''}`;
  box.querySelector('.stripe-platform-save')?.addEventListener('click', async (event) => {
    try {
      await api(endpoint, { method: 'PUT', body: JSON.stringify({
        clientId: box.querySelector('.stripe-platform-client').value,
        secretKey: box.querySelector('.stripe-platform-secret').value || undefined,
        webhookSecret: box.querySelector('.stripe-platform-webhook-secret').value || undefined,
      }) });
      toast('Stripe platform setup saved');
      await wireStripePlatformCard();
    } catch (error) { toast(error.message, true); }
  });
}

function paidLaunchCard() {
  return '<div class="card" id="paid-launch-card"><div class="task-sub">Loading paid-launch setup…</div></div>';
}

async function wirePaidLaunchCard() {
  const box = $('#paid-launch-card');
  if (!box) return;
  let state;
  try { state = await api('/api/settings/paid-launch'); }
  catch (error) { box.innerHTML = `<p class="task-sub">${esc(error.message)}</p>`; return; }
  const contacts = state.contacts || {};
  const stripe = state.stripe || {};
  const completed = new Set(state.completedTasks || []);
  const groups = [...new Set((state.tasks || []).map((task) => task.group))];
  const readiness = state.paidLaunch
    ? '<span class="chip" style="color:var(--ok,#4ec9a3)">paid checkout live</span>'
    : state.canEnable ? '<span class="chip" style="color:var(--ok,#4ec9a3)">ready to enable</span>'
      : '<span class="chip">setup incomplete</span>';
  const missing = [...(state.missing || []), ...(stripe.missing || [])];
  const taskMarkup = groups.map((group) => `<div class="section-h" style="margin-top:18px">${esc(group)}</div>${(state.tasks || [])
    .filter((task) => task.group === group).map((task) => `<label class="card" style="display:flex;gap:10px;padding:12px;margin:8px 0;cursor:pointer">
      <input type="checkbox" class="paid-launch-task" value="${esc(task.id)}" ${completed.has(task.id) ? 'checked' : ''} style="margin-top:3px;align-self:flex-start" />
      <span><b>${esc(task.title)}</b><span class="task-sub" style="display:block;margin-top:4px">${esc(task.instructions)} ${task.href ? `<a href="${esc(task.href)}" target="_blank" rel="noopener">Open official setup page ↗</a>` : ''}</span></span></label>`).join('')}`).join('');
  box.innerHTML = `<div class="section-h">Paid hosted launch ${readiness}</div>
    <p class="task-sub">This is the control center for selling krmax.io subscriptions. Values are saved with the installation; Stripe secrets are encrypted in the krmax vault and are never returned to the browser. No paid-launch environment variables are required.</p>
    ${missing.length ? `<p class="task-sub" style="color:var(--warn)"><b>Still required:</b> ${esc(missing.join(', '))}</p>` : ''}

    <div class="section-h" style="margin-top:18px">Stripe Billing</div>
    <p class="task-sub">This is SaaS subscription billing, separate from Stripe Connect for cards agents spend from. Start by <a href="https://dashboard.stripe.com/register" target="_blank" rel="noopener">creating a Stripe account</a> for the legal business and completing live-mode verification. krmax uses hosted Stripe Checkout, so it does not need a publishable key.</p>
    <ol class="task-sub"><li>Create the live recurring products/prices described in the founder checklist below.</li><li>In Stripe Workbench, create a snapshot webhook destination at <span class="mono">${esc(stripe.webhookUrl || '')}</span>, select API version <span class="mono">${esc(stripe.apiVersion || '')}</span>, and subscribe to: <span class="mono">${esc((stripe.webhookEvents || []).join(', '))}</span>.</li><li>Paste the live secret key, webhook signing secret, and IDs here. Blank secret fields keep the encrypted values already saved.</li><li>Configure and test the Stripe customer portal, then exercise the full lifecycle in test mode before enabling checkout.</li></ol>
    <div class="settings-grid">
      <label class="form-row">Stripe secret key<input class="paid-stripe-secret" type="password" autocomplete="new-password" placeholder="${stripe.secretKeyConfigured ? 'Configured — leave blank to keep' : 'sk_live_…'}" /></label>
      <label class="form-row">Webhook signing secret<input class="paid-stripe-webhook" type="password" autocomplete="new-password" placeholder="${stripe.webhookSecretConfigured ? 'Configured — leave blank to keep' : 'whsec_…'}" /></label>
      <label class="form-row">Individual $9 price ID<input class="paid-stripe-individual-price" value="${esc(stripe.individualPriceId || '')}" placeholder="price_…" /></label>
      <label class="form-row">Team $19 base price ID<input class="paid-stripe-team-base-price" value="${esc(stripe.teamBasePriceId || '')}" placeholder="price_…" /></label>
      <label class="form-row">Team $5 extra-user price ID<input class="paid-stripe-team-seat-price" value="${esc(stripe.teamSeatPriceId || '')}" placeholder="price_…" /></label>
      <label class="form-row">Individual product ID (optional)<input class="paid-stripe-individual-product" value="${esc(stripe.individualProductId || '')}" placeholder="prod_…" /></label>
      <label class="form-row">Team product ID (optional)<input class="paid-stripe-team-product" value="${esc(stripe.teamProductId || '')}" placeholder="prod_…" /></label>
      <label class="form-row">Webhook destination<input value="${esc(stripe.webhookUrl || '')}" readonly /></label>
    </div>

    <div class="section-h" style="margin-top:18px">Legal operator and public contacts</div>
    <p class="task-sub">Use the contracting entity’s exact details. These values populate public policies and support/deletion flows. Ask qualified counsel to review the supplied policy drafts for the business, jurisdiction, data flows, and customers.</p>
    <div class="settings-grid">
      <label class="form-row">Legal entity name<input class="paid-operator-name" value="${esc(state.operatorName || '')}" /></label>
      <label class="form-row">Country of establishment<input class="paid-operator-country" value="${esc(state.operatorCountry || '')}" /></label>
      <label class="form-row">Governing law and courts<input class="paid-governing-law" value="${esc(state.governingLaw || '')}" placeholder="e.g. laws of …; courts of …" /></label>
      <label class="form-row">Legal notice address<textarea class="paid-legal-address" rows="3">${esc(state.legalNoticeAddress || '')}</textarea></label>
      <label class="form-row">Legal email<input class="paid-email-legal" type="email" value="${esc(contacts.legal || '')}" /></label>
      <label class="form-row">Privacy email<input class="paid-email-privacy" type="email" value="${esc(contacts.privacy || '')}" /></label>
      <label class="form-row">Security email<input class="paid-email-security" type="email" value="${esc(contacts.security || '')}" /></label>
      <label class="form-row">Incident email<input class="paid-email-incident" type="email" value="${esc(contacts.incident || '')}" /></label>
      <label class="form-row">DPA email<input class="paid-email-dpa" type="email" value="${esc(contacts.dpa || '')}" /></label>
      <label class="form-row">Billing email<input class="paid-email-billing" type="email" value="${esc(contacts.billing || '')}" /></label>
    </div>
    <label class="card" style="display:flex;gap:10px;padding:12px;margin-top:14px"><input type="checkbox" class="paid-founder-reviewed" ${state.founderReviewed ? 'checked' : ''} /><span><b>I reviewed and approved policy version ${esc(state.policyVersion)}</b><span class="task-sub" style="display:block">This records founder approval; it is not a substitute for legal advice.</span></span></label>

    <div class="section-h" style="margin-top:22px">Real-world founder checklist</div>
    <p class="task-sub">These items happen outside krmax. Check them off here to keep one durable launch record; the checkboxes are guidance and do not falsely claim that krmax verified the work.</p>
    ${taskMarkup}

    <div class="card" style="margin-top:18px;padding:14px;border-color:${state.paidLaunch ? 'var(--ok,#4ec9a3)' : 'var(--line)'}">
      <label style="display:flex;gap:10px;align-items:flex-start"><input type="checkbox" class="paid-launch-enabled" ${state.paidLaunch ? 'checked' : ''} ${state.canEnable || state.paidLaunch ? '' : 'disabled'} /><span><b>Enable real paid checkout</b><span class="task-sub" style="display:block">Only turn this on after the legal and Stripe configuration is complete. Disabling it immediately closes new paid checkout without deleting subscriptions or settings.</span></span></label>
    </div>
    <button class="btn primary paid-launch-save" style="margin-top:14px" ${state.canManage ? '' : 'disabled'}>Save paid-launch setup</button>
    ${state.source === 'environment-bootstrap' ? '<p class="task-sub">Legacy environment values may currently be supplying some fields. Saving this form moves the editable configuration into Installation settings; saved values take precedence.</p>' : ''}`;
  box.querySelector('.paid-launch-save')?.addEventListener('click', async () => {
    try {
      await api('/api/settings/paid-launch', { method: 'PUT', body: JSON.stringify({
        paidLaunch: box.querySelector('.paid-launch-enabled').checked,
        founderReviewed: box.querySelector('.paid-founder-reviewed').checked,
        operatorName: box.querySelector('.paid-operator-name').value,
        operatorCountry: box.querySelector('.paid-operator-country').value,
        governingLaw: box.querySelector('.paid-governing-law').value,
        legalNoticeAddress: box.querySelector('.paid-legal-address').value,
        contacts: {
          legal: box.querySelector('.paid-email-legal').value,
          privacy: box.querySelector('.paid-email-privacy').value,
          security: box.querySelector('.paid-email-security').value,
          incident: box.querySelector('.paid-email-incident').value,
          dpa: box.querySelector('.paid-email-dpa').value,
          billing: box.querySelector('.paid-email-billing').value,
        },
        stripe: {
          secretKey: box.querySelector('.paid-stripe-secret').value || undefined,
          webhookSecret: box.querySelector('.paid-stripe-webhook').value || undefined,
          individualPriceId: box.querySelector('.paid-stripe-individual-price').value,
          teamBasePriceId: box.querySelector('.paid-stripe-team-base-price').value,
          teamSeatPriceId: box.querySelector('.paid-stripe-team-seat-price').value,
          individualProductId: box.querySelector('.paid-stripe-individual-product').value,
          teamProductId: box.querySelector('.paid-stripe-team-product').value,
        },
        completedTasks: [...box.querySelectorAll('.paid-launch-task:checked')].map((input) => input.value),
      }) });
      toast('Paid-launch setup saved');
      S.launch = await api('/api/launch');
      await wirePaidLaunchCard();
    } catch (error) { toast(error.message, true); await wirePaidLaunchCard(); }
  });
}
// ── card fields ──────────────────────────────────────────────────────────────
// Card number, expiry and CVC behave like any checkout form: separators appear
// as you type, a pasted number is regrouped whatever it was punctuated with,
// and Backspace over a separator takes the digit behind it. Only `format` is
// per-field; the caret bookkeeping below is shared.
/** Digit groups as the brand prints them on the card; the last entry is the default. */
const CARD_NUMBER_GROUPS = [
  { test: /^3[47]/, groups: [4, 6, 5] },              // American Express
  { test: /^3(?:0[0-59]|[689])/, groups: [4, 6, 4] }, // Diners Club / Carte Blanche
  { test: /^/, groups: [4, 4, 4, 4, 3] },             // everything else, up to 19 digits
];
/** "4242-4242 42424242" → "4242 4242 4242 4242"; Amex → "3782 822463 10005". */
function formatCardNumber(raw) {
  const all = String(raw ?? '').replace(/\D/g, '');
  const { groups } = CARD_NUMBER_GROUPS.find((brand) => brand.test.test(all));
  const digits = all.slice(0, groups.reduce((sum, size) => sum + size, 0));
  const out = [];
  for (let at = 0, g = 0; at < digits.length; at += groups[g++]) out.push(digits.slice(at, at + groups[g]));
  return out.join(' ');
}
/** Anything from "5" to "12 - 2026" → "MM/YY", inserting the slash as soon as the month is known. */
function formatExpiry(raw) {
  const s = String(raw ?? '').trim();
  // A month can only be one digit if it cannot start a two-digit month ("5"),
  // or if the user closed it with a separator themselves ("1/").
  let digits = (/^[1-9]/.test(s) && (s[0] > '1' || /^\d\D/.test(s)) ? '0' : '') + s.replace(/\D/g, '');
  if (digits.length > 4) digits = digits.slice(0, 2) + digits.slice(-2); // a 4-digit year
  const month = digits.slice(0, 2);
  return month.length < 2 ? month : `${month}/${digits.slice(2, 4)}`;
}
/** CVC: digits only, up to the four American Express prints (three elsewhere). */
function formatCvc(raw) {
  return String(raw ?? '').replace(/\D/g, '').slice(0, 4);
}
/** Offset in `value` just past its `count`-th digit — where the caret belongs. */
function caretAfterDigits(value, count) {
  if (count <= 0) return 0;
  let seen = 0;
  for (let i = 0; i < value.length; i++)
    if (value[i] >= '0' && value[i] <= '9' && ++seen === count) return i + 1;
  return value.length;
}
/** Reformat `raw`, keeping the caret on the same digit the user left it after. */
function applyDigitFormat(raw, caret, format) {
  const value = format(raw);
  // Typing at the end is the common case, and the only one where the format may
  // legitimately insert a digit ahead of the caret (a padded month).
  if (caret >= raw.length) return { value, caret: value.length };
  return { value, caret: caretAfterDigits(value, raw.slice(0, caret).replace(/\D/g, '').length) };
}
/** The span a delete should really cover: a separator drags its neighbouring digit along. */
function separatorDeletion(value, start, end, inputType) {
  if (start !== end) return null;
  if (inputType === 'deleteContentBackward' && start > 0 && !/\d/.test(value[start - 1]))
    return [Math.max(0, start - 2), start];
  if (inputType === 'deleteContentForward' && start < value.length && !/\d/.test(value[start]))
    return [start, start + 2];
  return null;
}
function wireCardField(input, format) {
  if (!input) return;
  const rewrite = (raw, caret) => {
    const next = applyDigitFormat(raw, caret, format);
    input.value = next.value;
    input.setSelectionRange(next.caret, next.caret);
  };
  input.addEventListener('beforeinput', (e) => {
    const span = separatorDeletion(input.value, input.selectionStart, input.selectionEnd, e.inputType);
    if (!span) return;
    e.preventDefault();
    rewrite(input.value.slice(0, span[0]) + input.value.slice(span[1]), span[0]);
  });
  input.addEventListener('input', () => rewrite(input.value, input.selectionStart ?? input.value.length));
}
/** "MM/YY", "MM/YYYY", or "MMYY" → {expMonth, expYear}; null when unparseable. */
function parseExpiry(raw) {
  const m = String(raw || '').trim().match(/^(\d{1,2})\s*[/\-\s]?\s*(\d{2}|\d{4})$/);
  if (!m) return null;
  const year = Number(m[2]);
  return { expMonth: Number(m[1]), expYear: year < 100 ? 2000 + year : year };
}
const usd = (cents) => `$${((cents || 0) / 100).toFixed(2)}`;
async function wirePaymentProviders(box, organizationId, onChange) {
  const list = box.querySelector('.pay-providers-list');
  if (!list) return;
  let data = { providers: [], active: null };
  const paymentsBase = organizationId
    ? `/api/organizations/${encodeURIComponent(organizationId)}/payments`
    : '/api/payments';
  try { data = await api(`${paymentsBase}/providers`); } catch {}
  // Only OAuth rails need a connect surface; the vault-card rail needs nothing
  // and the mock rail is a development fixture, not a user-facing choice.
  const connectable = data.providers.filter((p) => p.kind === 'oauth');
  list.innerHTML = connectable.map((p) => `<div class="queue-item" data-prov="${esc(p.name)}">
      <div style="flex:1">${p.connected ? '<span class="chip" style="color:var(--ok,#4ec9a3)">connected</span>' : p.connectionStatus === 'attention' ? '<span class="chip">needs attention</span>' : !p.available ? '<span class="chip">deployment setup needed</span>' : '<span class="chip">not connected</span>'}
        <div class="task-sub" style="color:var(--ink-3)">${esc(p.help || '')}</div></div>
      ${p.available && !p.connected ? `<button class="btn sm" data-connectpay="${esc(p.name)}">Connect</button>` : ''}
      ${p.connected || p.connectionStatus ? `<button class="btn sm danger" data-disconnectpay="${esc(p.name)}">Disconnect</button>` : ''}</div>`).join('');
  list.querySelectorAll('[data-connectpay]').forEach((b) => b.addEventListener('click', async () => {
    try {
      const r = await api(`${paymentsBase}/connect`, { method: 'POST', body: JSON.stringify({ provider: b.dataset.connectpay }) });
      if (r.status === 'awaiting_oauth' && r.url) {
        location.assign(r.url);
      } else if (r.status === 'connected') { toast('Connected'); await wirePaymentProviders(box, organizationId, onChange); }
      else { toast(r.detail || 'Not available', true); }
    } catch (e) { toast(e.message, true); }
  }));
  list.querySelectorAll('[data-disconnectpay]').forEach((b) => b.addEventListener('click', async () => {
    if (!confirm(`Disconnect ${b.dataset.disconnectpay} from this organization? Existing cards will be unusable.`)) return;
    try {
      await api(`${paymentsBase}/connections/${encodeURIComponent(b.dataset.disconnectpay)}`, { method: 'DELETE' });
      toast('Payment provider disconnected');
      await wirePaymentProviders(box, organizationId, onChange);
    } catch (e) { toast(e.message, true); }
  }));
  // Only a rail with a balance karmax can read has one worth showing.
  const el = box.querySelector('.pay-balance');
  if (el) el.innerHTML = '';
  if (organizationId && connectable.some((p) => p.name === 'stripe' && p.connected)) {
    try {
      const balance = await api(`${paymentsBase}/balance?provider=stripe`);
      if (el) el.innerHTML = `<b>Issuing balance:</b> ${usd(balance.available)} ${esc(String(balance.currency || 'usd').toUpperCase())}${balance.fundingUrl ? ` · <a href="${esc(balance.fundingUrl)}" target="_blank" rel="noopener">Fund in Stripe</a>` : ''}`;
    } catch {}
  }
  if (onChange) await onChange(data);
  return data;
}

async function syncPaymentProviderControls(box, providerData, paymentsBase) {
  const holderSelect = box.querySelector('.card-cardholder');
  const stripeConnected = (providerData?.providers || []).some((provider) => provider.name === 'stripe' && provider.connected);
  box.querySelector('.pay-cardholder')?.classList.toggle('hidden', !stripeConnected);
  box.querySelector('.stripe-issue')?.classList.toggle('hidden', !stripeConnected);
  if (!holderSelect) return;
  if (!stripeConnected) {
    holderSelect.innerHTML = '<option value="">Connect Stripe to load cardholders</option>';
    return;
  }
  try {
    const holders = await api(`${paymentsBase}/cardholders?provider=stripe`);
    holderSelect.innerHTML = `<option value="">Choose cardholder</option>${holders.map((holder) => {
      const requirements = holder.requirements?.past_due || [];
      const ready = holder.status === 'active' && requirements.length === 0;
      return `<option value="${ready ? esc(holder.id) : ''}" ${ready ? '' : 'disabled'}>${esc(holder.name)} · ${esc(holder.type)}${ready ? '' : ` · needs Stripe verification (${esc(requirements.join(', ') || holder.status)})`}</option>`;
    }).join('')}`;
  } catch {
    holderSelect.innerHTML = '<option value="">Cardholders unavailable</option>';
  }
}

async function wirePaymentsCard(scope, projectId, organizationId) {
  const box = $(`[data-payments="${scope}"]`);
  if (!box) return;
  // Non-project cards belong to the organization (tenant boundary), not the
  // whole installation. `scope==='global'` here is the org-settings surface.
  const orgQ = organizationId ? `organizationId=${encodeURIComponent(organizationId)}` : '';
  // Before any await: the card fields must format from the first keystroke even
  // if the provider lookup below is slow or fails.
  wireCardField(box.querySelector('.card-number'), formatCardNumber);
  wireCardField(box.querySelector('.card-expiry'), formatExpiry);
  wireCardField(box.querySelector('.card-cvc'), formatCvc);
  const paymentsBase = organizationId
    ? `/api/organizations/${encodeURIComponent(organizationId)}/payments`
    : '/api/payments';
  let providerData;
  if (scope === 'global') providerData = await wirePaymentProviders(box, organizationId, async (data) => {
    providerData = data;
    await syncPaymentProviderControls(box, data, paymentsBase);
  });
  else {
    try { providerData = await api(`${paymentsBase}/providers`); } catch { providerData = { providers: [], active: 'mock' }; }
    await syncPaymentProviderControls(box, providerData, paymentsBase);
  }
  const holderSelect = box.querySelector('.card-cardholder');
  box.querySelector('[data-addholder]')?.addEventListener('click', async () => {
    const dobValue = box.querySelector('.holder-dob').value;
    const dob = dobValue ? new Date(`${dobValue}T00:00:00Z`) : undefined;
    try {
      await api(`${paymentsBase}/cardholders`, { method: 'POST', body: JSON.stringify({
        provider: 'stripe',
        type: box.querySelector('.holder-type').value,
        name: box.querySelector('.holder-name').value.trim(),
        firstName: box.querySelector('.holder-first').value.trim() || undefined,
        lastName: box.querySelector('.holder-last').value.trim() || undefined,
        dob: dob ? { day: dob.getUTCDate(), month: dob.getUTCMonth() + 1, year: dob.getUTCFullYear() } : undefined,
        email: box.querySelector('.holder-email').value.trim() || undefined,
        phone: box.querySelector('.holder-phone').value.trim() || undefined,
        address: {
          line1: box.querySelector('.holder-line1').value.trim(),
          city: box.querySelector('.holder-city').value.trim(),
          state: box.querySelector('.holder-state').value.trim() || undefined,
          postalCode: box.querySelector('.holder-postal').value.trim(),
          country: box.querySelector('.holder-country').value.trim(),
        },
      }) });
      toast('Stripe cardholder created');
      await syncPaymentProviderControls(box, providerData, paymentsBase);
    } catch (e) { toast(e.message, true); }
  });
  const sUrl = scope === 'global' && organizationId
    ? `/api/organizations/${encodeURIComponent(organizationId)}/settings/payments`
    : scope === 'global' ? '/api/settings/global/payments' : `/api/settings/project/${projectId}/payments`;
  let policy = {};
  try { policy = await api(sUrl); } catch {}
  if (policy.allowance != null) box.querySelector('.pay-allow').value = (policy.allowance / 100).toFixed(2);
  if (policy.threshold != null) box.querySelector('.pay-thresh').value = (policy.threshold / 100).toFixed(2);
  box.querySelector(`[data-savepolicy]`).addEventListener('click', async () => {
    const a = box.querySelector('.pay-allow').value;
    const t = box.querySelector('.pay-thresh').value;
    const values = { ...policy };
    values.allowance = a === '' ? undefined : Math.round(Number(a) * 100);
    values.threshold = t === '' ? undefined : Math.round(Number(t) * 100);
    try { await api(sUrl, { method: 'PUT', body: JSON.stringify({ values }) }); toast('Budget policy saved'); } catch (e) { toast(e.message, true); }
  });
  const renderCards = async () => {
    let cards = [];
    const q = [projectId ? `projectId=${projectId}` : '', orgQ].filter(Boolean).join('&');
    try { cards = await api(`/api/cards${q ? `?${q}` : ''}`); } catch {}
    // The org-settings surface shows the org's own cards (+ legacy global);
    // the project surface shows project cards (its org's cards appear too).
    if (scope === 'global') cards = cards.filter((c) => c.scope === 'organization' || c.scope === 'global');
    const list = box.querySelector('.cards-list');
    list.innerHTML = cards.length
      ? cards.map((c) => `<div class="queue-item"><div style="flex:1"><b>${esc(c.label)}</b> ${c.last4 ? `<span class="mono">•••• ${esc(c.last4)}</span>` : ''}${c.status && c.status !== 'active' ? ` <span class="chip">${esc(c.status)}</span>` : ''}
          <div class="task-sub">${usd(c.remaining ?? c.available)} of ${usd(c.cap)} left${c.merchantLock?.length ? ` · ${c.merchantLock.map(esc).join(', ')} only` : ''}</div></div>
        ${c.provider === 'vault-card' && c.status !== 'canceled' ? `<button class="btn sm" data-fund="${c.id}" title="Match the limit you set with your bank">Raise limit</button>` : ''}
        ${c.status !== 'canceled' ? `<button class="btn sm danger" data-revoke="${c.id}">Revoke</button>` : ''}</div>`).join('')
      : '<span style="color:var(--ink-3)">No cards yet.</span>';
    list.querySelectorAll('[data-fund]').forEach((b) => b.addEventListener('click', async () => {
      const amt = prompt('Raise this card’s limit by how much (USD)? Raise it with your bank first — krmax only mirrors the figure.');
      if (amt == null) return;
      if (!Number(amt) || Number(amt) < 0) return toast('Enter an amount greater than zero.', true);
      try { await api(`/api/cards/${b.dataset.fund}/fund${orgQ ? `?${orgQ}` : ''}`, { method: 'POST', body: JSON.stringify({ amount: Math.round(Number(amt) * 100) }) }); toast('Limit raised'); renderCards(); } catch (e) { toast(e.message, true); }
    }));
    list.querySelectorAll('[data-revoke]').forEach((b) => b.addEventListener('click', async () => {
      if (!confirm('Revoke this card? This cannot be undone.')) return;
      try {
        await api(`/api/cards/${b.dataset.revoke}${orgQ ? `?${orgQ}` : ''}`, { method: 'DELETE' });
        toast('Card revoked');
        renderCards();
      } catch (e) { toast(e.message, true); }
    }));
  };
  await renderCards();
  const field = (name) => box.querySelector(name).value.trim();
  const addCard = (body) => api(`/api/cards${orgQ ? `?${orgQ}` : ''}`, { method: 'POST', body: JSON.stringify({
    scope: scope === 'project' ? 'project' : 'organization',
    projectId: scope === 'project' ? projectId : undefined,
    ...body,
  }) });
  box.querySelector('[data-addcard]').addEventListener('click', async () => {
    const expiry = parseExpiry(field('.card-expiry'));
    if (!expiry) return toast('Expiry must look like MM/YY', true);
    try {
      await addCard({
        provider: 'vault-card',
        label: field('.card-label') || 'Card',
        cap: Math.round(Number(field('.card-cap') || 0) * 100),
        merchantLock: field('.card-merchants').split(',').map((value) => value.trim()).filter(Boolean),
        details: {
          number: field('.card-number'),
          cvc: field('.card-cvc'),
          ...expiry,
          billing: { line1: field('.card-line1'), city: field('.card-city'),
            postalCode: field('.card-postal'), country: field('.card-country') },
        },
      });
      // Clear the secret half from the DOM as soon as it has been vaulted.
      for (const name of ['.card-label', '.card-cap', '.card-merchants', '.card-number', '.card-expiry',
        '.card-cvc', '.card-line1', '.card-city', '.card-postal', '.card-country'])
        box.querySelector(name).value = '';
      toast('Card added');
      renderCards();
    } catch (e) { toast(e.message, true); }
  });
  box.querySelector('[data-issuecard]')?.addEventListener('click', async () => {
    try {
      await addCard({
        provider: 'stripe',
        label: field('.sc-label') || 'Card',
        cap: Math.round(Number(field('.sc-cap') || 0) * 100),
        cardholderId: holderSelect.value,
      });
      box.querySelector('.sc-label').value = '';
      box.querySelector('.sc-cap').value = '';
      toast('Card issued');
      renderCards();
    } catch (e) { toast(e.message, true); }
  });
  if (scope === 'global' && organizationId) {
    const renderLedger = async () => {
      let requests = [], transactions = [];
      try { [requests, transactions] = await Promise.all([
        api(`${paymentsBase}/requests`), api(`${paymentsBase}/transactions`),
      ]); } catch {}
      const pending = requests.filter((r) => ['pending_approval', 'needs_funding', 'authorized', 'consumed'].includes(r.status));
      box.querySelector('.pay-requests').innerHTML = pending.length ? pending.map((r) =>
        `<div class="queue-item"><div style="flex:1"><b>${usd(r.amount)}</b> ${r.merchant ? `at ${esc(r.merchant)}` : ''} <span class="chip">${esc(r.status)}</span><div class="task-sub">${esc(r.why || r.reason || '')}</div></div>
          ${['pending_approval', 'needs_funding'].includes(r.status) ? `<button class="btn sm" data-payapprove="${r.id}">Approve / retry</button><button class="btn sm danger" data-paydeny="${r.id}">Deny</button>` : ''}</div>`).join('')
        : '<span style="color:var(--ink-3)">No pending requests.</span>';
      box.querySelector('.pay-transactions').innerHTML = transactions.length ? transactions.slice(0, 50).map((t) =>
        `<div class="queue-item"><div style="flex:1"><b>${usd(t.amount)}</b> ${t.merchant ? `at ${esc(t.merchant)}` : ''} <span class="chip">${esc(t.status)}</span><div class="task-sub">${esc(t.provider)} · ${new Date(t.createdAt).toLocaleString()}</div></div></div>`).join('')
        : '<span style="color:var(--ink-3)">No payment activity.</span>';
      box.querySelectorAll('[data-payapprove],[data-paydeny]').forEach((b) => b.addEventListener('click', async () => {
        const id = b.dataset.payapprove || b.dataset.paydeny;
        const op = b.dataset.payapprove ? 'approve' : 'deny';
        try {
          const r = await api(`${paymentsBase}/requests/${encodeURIComponent(id)}/${op}`, { method: 'POST' });
          toast(r.status === 'granted' ? 'Spend approved' : r.reason || 'Request updated', r.status === 'denied');
          renderLedger();
        } catch (e) { toast(e.message, true); }
      }));
    };
    await renderLedger();
  }
}

// ── vault items + credential access requests (PLAN-passwords.md §§4–10) ──────
const VAULT_SECRET_LABELS = {
  login: [['password', 'password'], ['totp', 'TOTP seed (base32, otpauth:// URI, or paste image of QR code)']],
  'api-key': [['secret', 'API key']],
  'ssh-key': [['privateKey', 'private key (PEM)']],
  env: [['env', '.env contents (KEY=VALUE per line)']],
  note: [['note', 'note']],
};
// Short label + click-to-expand explanation for the two per-item policies.
const POL_USE_TIP = 'Blind use = the agent fills this into a login form or gets it as an environment variable, but never sees the secret text itself. “ask” makes it request your approval each time.';
const POL_REVEAL_TIP = 'Agent sees = the plaintext secret is handed to the agent (needed e.g. to paste an API key into a dashboard). “never” forbids that entirely; “ask” requires your approval each time.';
// `title` covers hover on desktop; the click handler is for touch, where there is
// no hover. It used to call `alert()` — the only modal in a console that speaks in
// toasts, and on desktop it fired *on top of* the native tooltip.
// The click is wired by delegation (installInfoDotTips), NOT by an inline
// `onclick`: app.js is loaded as `<script type="module">`, so every function here
// is module-scoped and invisible to an inline attribute handler. An inline
// `onclick="window.__toast(…)"` threw `TypeError: window.__toast is not a
// function` on every tap — silently breaking the affordance for exactly the
// touch users it was added for.
function policyTip(text) { return `<button type="button" class="info-dot" title="${esc(text)}" aria-label="${esc(text)}">ⓘ</button>`; }

function clearTotpQrPreview(control, clearValue = false) {
  if (!control) return;
  control.totpQrPaste = null;
  const preview = control.querySelector('.totp-qr-preview');
  const image = preview?.querySelector('img');
  const objectUrl = preview?.dataset.objectUrl;
  if (objectUrl) URL.revokeObjectURL(objectUrl);
  if (preview) {
    preview.hidden = true;
    preview.dataset.objectUrl = '';
    preview.dataset.state = '';
  }
  image?.removeAttribute('src');
  control.classList.remove('has-qr');
  if (clearValue) control.querySelector('.vi-totp-input').value = '';
}

function wireTotpQrPaste(root) {
  root.querySelectorAll('.totp-secret-control').forEach((control) => {
    const input = control.querySelector('.vi-totp-input');
    const preview = control.querySelector('.totp-qr-preview');
    const imageElement = preview.querySelector('img');
    const status = preview.querySelector('.totp-qr-status');
    input.addEventListener('paste', async (event) => {
      const item = [...(event.clipboardData?.items || [])].find((item) => item.type.startsWith('image/'));
      const image = item?.getAsFile();
      if (!image) return;
      event.preventDefault();
      if (image.size > 10 * 1024 * 1024) {
        toast('TOTP QR image is larger than 10 MB', true);
        return;
      }
      clearTotpQrPreview(control);
      input.value = '';
      const objectUrl = URL.createObjectURL(image);
      preview.dataset.objectUrl = objectUrl;
      preview.dataset.state = 'reading';
      preview.hidden = false;
      imageElement.src = objectUrl;
      status.textContent = 'Reading QR…';
      control.classList.add('has-qr');
      const paste = Symbol('totp-qr-paste');
      control.totpQrPaste = paste;
      try {
        const value = await decodeTotpQrImage(image);
        if (control.totpQrPaste !== paste) return;
        input.value = value;
        preview.dataset.state = 'ready';
        status.textContent = 'QR added';
      } catch (error) {
        if (control.totpQrPaste !== paste) return;
        preview.dataset.state = 'error';
        status.textContent = 'Not readable';
        toast(error.message, true);
      }
    });
    input.addEventListener('input', () => clearTotpQrPreview(control));
    preview.querySelector('.totp-qr-remove').addEventListener('click', () => {
      control.totpQrPaste = null;
      clearTotpQrPreview(control, true);
      input.focus();
    });
  });
}

function credentialRequestTaskLink(request) {
  const task = request.task || taskRecord(request.taskId);
  if (!task) return `<span class="mono">${esc(request.taskId)}</span>`;
  const project = projectById(task.projectId);
  const key = task.num != null ? task.num : task.id;
  const label = `${task.num != null ? `#${task.num} · ` : ''}${task.title}`;
  return project
    ? `<a data-spa href="${projectBase(project.id)}/tasks/${encodeURIComponent(key)}/approvals">${esc(label)}</a>`
    : `<span>${esc(label)}</span>`;
}

function credentialRequestRows(requests, items, { historyLimit = 5, showEmpty = true } = {}) {
  const itemLabel = (id) => items.find((item) => item.id === id)?.label || id;
  const pending = requests.filter((request) => request.status === 'pending');
  const recent = requests.filter((request) => request.status !== 'pending').slice(-historyLimit).reverse();
  const pendingHtml = pending.length
    ? pending.map((request) => `<div class="approval-request" data-vreq="${esc(request.id)}">
        <div class="approval-request-main">
          <div class="approval-request-title">${request.itemId
            ? esc(itemLabel(request.itemId))
            : `${esc(request.domain || '?')} <span class="chip approval-needed">not in vault</span>`}
            ${request.kind === 'reset' ? '<span class="chip approval-needed">reported invalid</span>' : `<span class="chip">${esc(request.mode)}</span>`}
          </div>
          <div class="task-sub">${credentialRequestTaskLink(request)}${request.why ? ` — ${esc(request.why)}` : ''}</div>
          ${request.kind === 'reset' ? '<div class="approval-request-help">The stored secret failed. Update it or send the task a reset code, then approve; krmax will resume the agent automatically.</div>' : ''}
        </div>
        <div class="approval-request-actions">
          ${request.itemId ? '' : `<select class="vreq-bind" aria-label="Credential to grant"><option value="">Choose credential…</option>${items.map((item) => `<option value="${esc(item.id)}">${esc(item.label)}</option>`).join('')}</select>`}
          <button class="btn sm" data-vreq-act="once">Once</button>
          <button class="btn sm" data-vreq-act="task">This task</button>
          <button class="btn sm" data-vreq-act="always">Always</button>
          <button class="btn sm" data-vreq-act="deny">Deny</button>
        </div>
      </div>`).join('')
    : showEmpty ? '<div class="approval-empty">No pending approval requests.</div>' : '';
  const history = recent.length
    ? `<div class="approval-history"><div class="section-h">Recent decisions</div>${recent.map((request) =>
      `<div class="approval-history-row"><span class="chip ${request.status === 'denied' ? 'failed' : 'done'}">${esc(request.status)}</span>
        <span>${request.itemId ? esc(itemLabel(request.itemId)) : esc(request.domain || '?')}</span>
        <span class="task-sub">${esc(request.resolution?.action || '')}</span></div>`).join('')}</div>`
    : '';
  return pendingHtml + history;
}

function permissionRequestRows(requests, { historyLimit = 20 } = {}) {
  const pending = requests.filter((request) => request.status === 'pending');
  const recent = requests.filter((request) => request.status !== 'pending').slice(-historyLimit).reverse();
  const pendingHtml = pending.map((request) => `<div class="approval-request" data-preq="${esc(request.id)}">
    <div class="approval-request-main">
      <div class="approval-request-title">${esc(request.role || 'task')} agent permission
        <span class="chip approval-needed">approval needed</span>
      </div>
      <div class="approval-request-caps">${request.capabilities.map((capability) =>
        `<span class="chip mono">${esc(capability)}</span>`).join(' ')}</div>
      <div class="task-sub">${credentialRequestTaskLink(request)} — ${esc(request.reason)}</div>
      <div class="approval-request-help">Requested from ${request.audience.map(esc).join(', ')}. Approval grants only these exact capabilities to this task’s ${esc(request.role || 'requesting')} agent.</div>
    </div>
    <div class="approval-request-actions">
      <button class="btn sm primary" data-preq-act="approve">Approve for agent</button>
      <button class="btn sm" data-preq-act="deny">Deny</button>
    </div>
  </div>`).join('');
  const history = recent.length
    ? `<div class="approval-history"><div class="section-h">Recent permission decisions</div>${recent.map((request) =>
      `<div class="approval-history-row"><span class="chip ${request.status === 'denied' ? 'failed' : 'done'}">${esc(request.status)}</span>
        <span class="mono">${request.capabilities.map(esc).join(', ')}</span>
        <span class="task-sub">${esc(request.resolution?.action || '')}</span></div>`).join('')}</div>`
    : '';
  return pendingHtml + history;
}

function authorizationRequestRows(requests, { historyLimit = 20 } = {}) {
  const signedInUserId = typeof S.user === 'string' ? S.user : S.user?.id;
  const pending = requests.filter((request) => request.status === 'pending');
  const recent = requests.filter((request) => request.status !== 'pending').slice(-historyLimit).reverse();
  const pendingHtml = pending.map((request) => {
    const canResolve = signedInUserId && request.recipients.includes(signedInUserId);
    return `<div class="approval-request" data-areq="${esc(request.id)}">
    <div class="approval-request-main">
      <div class="approval-request-title">${request.target.kind === 'avatar' ? 'Avatar' : 'Task agent'} authorization
        <span class="chip approval-needed">approval needed</span>
      </div>
      <div class="approval-request-caps"><span class="chip">${esc(authorizationSummary(request.authorization,
        S.projects.filter((project) => project.organizationId === request.organizationId)))}</span></div>
      <div class="task-sub">${esc(request.reason)}</div>
      <div class="approval-request-help">Requested from ${request.audience.map(esc).join(', ')}. Approval delegates this authorization directly to the ${esc(request.target.kind)}; it does not elevate the requester.</div>
    </div>
    <div class="approval-request-actions">
      ${canResolve ? '<button class="btn sm primary" data-areq-act="approve">Approve authorization</button><button class="btn sm" data-areq-act="deny">Deny</button>'
        : '<span class="task-sub">Awaiting a routed approver</span>'}
    </div>
  </div>`;
  }).join('');
  const history = recent.length ? `<div class="approval-history"><div class="section-h">Recent authorization decisions</div>${recent.map((request) =>
    `<div class="approval-history-row"><span class="chip ${request.status === 'denied' ? 'failed' : 'done'}">${esc(request.status)}</span>
      <span>${esc(authorizationSummary(request.authorization, S.projects))}</span>
      <span class="task-sub">${esc(request.resolution?.action || '')}</span></div>`).join('')}</div>` : '';
  return pendingHtml + history;
}

function wireAuthorizationRequestActions(root, organizationId, onResolved) {
  if (!root) return;
  root.querySelectorAll('[data-areq]').forEach((row) => row.querySelectorAll('[data-areq-act]').forEach((button) =>
    button.addEventListener('click', async () => {
      button.disabled = true;
      try {
        const result = await api(`/api/authorization-requests/${row.dataset.areq}/resolve?organizationId=${encodeURIComponent(organizationId || '')}`, {
          method: 'POST', body: JSON.stringify({ action: button.dataset.areqAct }),
        });
        toast(button.dataset.areqAct === 'deny' ? 'Authorization denied'
          : result.queued ? 'Approved — task queued' : 'Authorization approved');
        await onResolved?.(result);
      } catch (error) { button.disabled = false; toast(error.message, true); }
    })));
}

function wirePermissionRequestActions(root, organizationId, onResolved) {
  if (!root) return;
  root.querySelectorAll('[data-preq]').forEach((row) => row.querySelectorAll('[data-preq-act]').forEach((button) =>
    button.addEventListener('click', async () => {
      button.disabled = true;
      try {
        const result = await api(`/api/permission-requests/${row.dataset.preq}/resolve?organizationId=${encodeURIComponent(organizationId || '')}`, {
          method: 'POST',
          body: JSON.stringify({ action: button.dataset.preqAct }),
        });
        const decision = button.dataset.preqAct === 'deny' ? 'Denied' : 'Approved';
        toast(result.resume?.resumed ? `${decision} — task resumed automatically`
          : `${decision}${result.resume?.reason ? ` — ${result.resume.reason}` : ''}`,
        !result.resume?.resumed && !!result.resume?.reason);
        await onResolved?.(result);
      } catch (error) {
        button.disabled = false;
        toast(error.message, true);
      }
    })));
}

function wireCredentialRequestActions(root, organizationId, onResolved) {
  if (!root) return;
  root.querySelectorAll('[data-vreq]').forEach((row) => row.querySelectorAll('[data-vreq-act]').forEach((button) => button.addEventListener('click', async () => {
    const itemId = row.querySelector('.vreq-bind')?.value || undefined;
    button.disabled = true;
    try {
      const result = await api(`/api/vault/requests/${row.dataset.vreq}/resolve?organizationId=${encodeURIComponent(organizationId || '')}`, {
        method: 'POST',
        body: JSON.stringify({ action: button.dataset.vreqAct, itemId }),
      });
      const decision = button.dataset.vreqAct === 'deny' ? 'Denied' : 'Granted';
      toast(result.resume?.resumed ? `${decision} — task resumed automatically`
        : `${decision}${result.resume?.reason ? ` — ${result.resume.reason}` : ''}`, !result.resume?.resumed && !!result.resume?.reason);
      await onResolved?.(result);
    } catch (error) {
      button.disabled = false;
      toast(error.message, true);
    }
  })));
}

/**
 * Import a connector selection in batches, reporting progress as they land.
 * Reading a secret out of a real store is expensive — a `pass` entry costs a
 * GPG decrypt, and a whole tree takes minutes — so a single blocking request
 * looks exactly like a dead button. Batching keeps the UI honest, commits what
 * has been read so far, and lets the server skip entries that have not changed.
 */
async function importFromConnector(sync, externalIds, onProgress, batchSize = 25) {
  const totals = { imported: 0, skipped: 0, failures: [], done: 0, total: externalIds.length };
  for (let at = 0; at < externalIds.length; at += batchSize) {
    onProgress?.(totals);
    const result = await sync(externalIds.slice(at, at + batchSize));
    totals.imported += result.count || 0;
    totals.skipped += result.skipped || 0;
    totals.failures.push(...(result.failures || []));
    totals.done = Math.min(at + batchSize, externalIds.length);
  }
  onProgress?.(totals);
  return totals;
}

