function billingRequestKey() {
  try { return crypto.randomUUID(); } catch { return `billing-${Date.now()}-${Math.random().toString(36).slice(2)}`; }
}

async function hydrateOrganizationSubscription(organizationId) {
  const box = $('#org-subscription');
  if (!box) return;
  let state;
  try { state = await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/status`); }
  catch (error) { box.innerHTML = `<p class="task-sub" style="color:var(--danger)">${esc(error.message)}</p>`; return; }
  if (!$('#org-subscription') || S.organizationId !== organizationId) return;
  if (!state.managed) {
    box.innerHTML = `<div class="section-h">Self-hosted <span class="chip">unmetered</span></div>
      <p class="task-sub">Hosted subscription billing does not apply to this private installation. Your organization plans and agent payment cards remain locally managed.</p>`;
    return;
  }
  const catalog = Object.fromEntries((state.catalog || []).map((plan) => [plan.id, plan]));
  const names = Object.fromEntries(Object.values(catalog).map((plan) => [plan.id, plan.name]));
  const price = (cents) => `$${(Number(cents || 0) / 100).toLocaleString(undefined,
    { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
  const statusNames = { none: 'free', active: 'active', trialing: 'trial', past_due: 'payment failed',
    unpaid: 'unpaid', incomplete: 'checkout incomplete', incomplete_expired: 'checkout expired',
    paused: 'paused', canceled: 'canceled' };
  const problem = ['past_due', 'unpaid', 'incomplete', 'incomplete_expired', 'paused'].includes(state.status);
  const period = state.currentPeriodEnd ? new Date(state.currentPeriodEnd).toLocaleDateString() : '';
  const billedPlan = state.billedPlan || state.plan;
  const hasSubscription = billedPlan !== 'free' && !['none', 'canceled', 'incomplete_expired'].includes(state.status);
  const seats = billedPlan === 'team'
    ? `<b>${state.activeUsers}</b> active user${state.activeUsers === 1 ? '' : 's'} · <b>${state.seats}</b> verified billed seat${state.seats === 1 ? '' : 's'}${state.seatDeficit ? ` · <span style="color:var(--danger)">${state.seatDeficit} awaiting reconciliation</span>` : ''}`
    : `<b>${state.activeUsers}</b> of 1 user`;
  const grace = state.access === 'grace' && state.graceEndsAt
    ? ` Access continues through ${new Date(state.graceEndsAt).toLocaleDateString()}.` : '';
  const checkoutReturn = new URLSearchParams(location.search).get('billing');
  const checkoutNotice = checkoutReturn === 'success'
    ? '<div class="card" style="margin:12px 0;padding:12px;border-color:var(--ok,#4ec9a3)"><b>Checkout completed</b><p class="task-sub">Waiting for Stripe’s signed subscription confirmation. This page will show the new plan after reconciliation.</p></div>'
    : checkoutReturn === 'canceled'
      ? '<div class="card" style="margin:12px 0;padding:12px"><b>Checkout canceled</b><p class="task-sub">No plan change was applied.</p></div>' : '';
  const alert = problem ? `<div class="card" style="margin:12px 0;padding:12px;border-color:var(--danger)"><b>Billing needs attention</b><p class="task-sub">${esc(state.lastError || 'Open the billing portal to update the payment method. Plan access may be restricted until Stripe confirms payment.')}${esc(grace)}</p></div>` : '';
  const individual = catalog.individual || {};
  const team = catalog.team || {};
  const ownerDisabled = state.canManage ? '' : 'disabled title="Only an organization owner can administer this subscription"';
  const checkoutReady = state.providerConfigured && S.launch?.paidLaunch && S.launch?.ready;
  const teamTotal = Number(team.monthlyBasePriceCents || 0)
    + Math.max(0, Number(state.activeUsers || 0) - Number(team.includedActiveUsers || 1))
      * Number(team.monthlyAdditionalActiveUserPriceCents || 0);
  const teamConcurrency = Number(team.maxActiveAgentRuns || 0)
    + Math.max(0, Number(state.activeUsers || 0) - Number(team.includedActiveUsers || 1))
      * Number(team.additionalActiveUserAgentRuns || 0);
  const disclosures = S.launch?.checkoutDisclosures || {};
  const planCards = !hasSubscription ? `<div class="billing-commercial-terms">
      <b>Before checkout</b><p class="task-sub">${esc(disclosures.renewalDisclosure || 'Subscriptions renew monthly until canceled.')} ${esc(disclosures.cancellationDisclosure || 'Cancel online from Organization settings before renewal.')} ${esc(disclosures.refundDisclosure || 'Payments are non-refundable except where law requires.')}</p>
      ${policyAcceptanceMarkup('checkout', 'checkout-policy-acceptance')}</div>
    <div class="settings-grid" style="margin-top:14px">
      <div class="card" style="padding:14px"><b>${esc(individual.name || 'Individual')}</b><div class="section-h" style="margin-top:6px">${esc(price(individual.monthlyBasePriceCents))} / month</div><p class="task-sub">${esc(individual.includedActiveUsers || 1)} user · unlimited projects · ${esc(individual.maxActiveAgentRuns)} shared concurrent agent runs.</p><button class="btn sm primary billing-checkout" data-plan="individual" ${checkoutReady ? ownerDisabled : 'disabled'}>Choose Individual</button></div>
      <div class="card" style="padding:14px"><b>${esc(team.name || 'Team')}</b><div class="section-h" style="margin-top:6px">${esc(price(team.monthlyBasePriceCents))} / month</div><p class="task-sub">First active user included, then ${esc(price(team.monthlyAdditionalActiveUserPriceCents))} / additional active user / month. With ${esc(state.activeUsers)} active user${state.activeUsers === 1 ? '' : 's'}: ${esc(price(teamTotal))} / month and ${esc(teamConcurrency)} shared concurrent agent runs. Unlimited projects · ${esc(team.maxActiveAgentRuns)} base concurrency + ${esc(team.additionalActiveUserAgentRuns)} per additional active user.</p><button class="btn sm primary billing-checkout" data-plan="team" ${checkoutReady ? ownerDisabled : 'disabled'}>Choose Team</button></div>
      <div class="card" style="padding:14px"><b>Enterprise</b><p class="task-sub">Custom deployment and support. Not available as a self-service launch plan.</p></div></div>` : '';
  const downgradeDisabled = ownerDisabled || (state.activeUsers > 1
    ? 'disabled title="Remove additional active users first"' : '');
  const changes = billedPlan === 'individual' && ['active', 'trialing', 'past_due'].includes(state.status)
    ? `<button class="btn sm billing-change" data-plan="team" ${ownerDisabled}>Upgrade to Team</button>`
    : billedPlan === 'team' && ['active', 'trialing', 'past_due'].includes(state.status)
      ? `<button class="btn sm billing-change" data-plan="individual" ${downgradeDisabled}>Downgrade to Individual</button>` : '';
  const effective = state.plan !== billedPlan ? ` · effective access: ${esc(names[state.plan] || state.plan)}` : '';
  box.innerHTML = `<div class="member-row"><span><span class="section-h">${esc(names[billedPlan] || billedPlan)} <span class="chip">${esc(statusNames[state.status] || state.status)}</span></span><span class="task-sub">${seats}${effective}</span></span>
    <span class="team-actions">${state.cancelAtPeriodEnd ? `<span class="chip">ends ${esc(period || 'after this period')}</span>` : period ? `<span class="task-sub">Renews ${esc(period)}</span>` : ''}</span></div>
    ${checkoutNotice}${alert}${!state.providerConfigured ? '<p class="task-sub" style="color:var(--warn)">Checkout is temporarily unavailable because hosted billing has not been configured by the operator.</p>' : ''}${state.providerConfigured && !checkoutReady ? '<p class="task-sub" style="color:var(--warn)">Checkout is disabled until the operator completes and enables the founder-reviewed paid-launch configuration.</p>' : ''}${!state.canManage ? '<p class="task-sub">Only an organization owner can administer this subscription.</p>' : ''}
    ${planCards}<div class="inline-form" style="margin-top:14px">${changes}${hasSubscription ? `<button class="btn sm billing-portal" ${ownerDisabled}>Billing portal</button>` : ''}${hasSubscription && !state.cancelAtPeriodEnd && ['active', 'trialing', 'past_due'].includes(state.status) ? `<button class="btn sm danger billing-cancel" ${ownerDisabled}>Cancel online at period end</button>` : ''}${state.seatDeficit && billedPlan === 'team' ? `<button class="btn sm billing-sync" ${ownerDisabled}>Reconcile seats</button>` : ''}</div>
    <p class="task-sub" style="margin-top:12px">Subscription charges are separate from cards agents use for purchases. Plan and seat access changes only after a signed billing event is reconciled. ${policyLinks(['billing'])}</p>`;
  box.querySelectorAll('.billing-checkout').forEach((button) => button.addEventListener('click', async () => {
    button.disabled = true;
    try {
      const acceptance = readPolicyAcceptance('checkout');
      const result = await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/checkout`, {
        method: 'POST', headers: { 'idempotency-key': billingRequestKey() }, body: JSON.stringify({
          plan: button.dataset.plan, acceptedPolicies: acceptance.accepted, policyVersions: acceptance.versions,
        }),
      });
      location.assign(result.url);
    } catch (error) { button.disabled = false; toast(error.message, true); }
  }));
  box.querySelector('.billing-portal')?.addEventListener('click', async (event) => {
    event.currentTarget.disabled = true;
    try { location.assign((await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/portal`, {
      method: 'POST', headers: { 'idempotency-key': billingRequestKey() },
    })).url); } catch (error) { event.currentTarget.disabled = false; toast(error.message, true); }
  });
  box.querySelector('.billing-change')?.addEventListener('click', async (event) => {
    const plan = event.currentTarget.dataset.plan;
    if (!confirm(`Change this organization to ${names[plan]}? Stripe will prorate the current billing period.`)) return;
    try { await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/change`, {
      method: 'POST', headers: { 'idempotency-key': billingRequestKey() }, body: JSON.stringify({ plan }),
    }); toast('Plan change submitted. Waiting for Stripe confirmation.'); await hydrateOrganizationSubscription(organizationId); }
    catch (error) { toast(error.message, true); }
  });
  box.querySelector('.billing-cancel')?.addEventListener('click', async () => {
    if (!confirm('Cancel this subscription at the end of its current billing period?')) return;
    try { await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/cancel`, {
      method: 'POST', headers: { 'idempotency-key': billingRequestKey() },
    }); toast('Cancellation submitted. Waiting for Stripe confirmation.'); await hydrateOrganizationSubscription(organizationId); }
    catch (error) { toast(error.message, true); }
  });
  box.querySelector('.billing-sync')?.addEventListener('click', async () => {
    try { await api(`/api/organizations/${encodeURIComponent(organizationId)}/subscription/sync-seats`, {
      method: 'POST', headers: { 'idempotency-key': billingRequestKey() },
    }); toast('Seat reconciliation submitted.'); } catch (error) { toast(error.message, true); }
  });
}

function wireInstallationSettings() {
  wireSettingsNavigation();
  wireAppearanceCard();
  wireHostCapacityCard();
  wireInstallationGithubCard();
  wirePaidLaunchCard();
  wireStripePlatformCard();
  wireOutboundEmailCard();
  hydrateResilienceCard();
  if (hostLocal()) hydratePhoneAccess();
}

function organizationView() {
  const org = S.organizations.find((o) => o.id === S.organizationId);
  const authorizationProjects = S.projects.filter((project) => project.organizationId === S.organizationId);
  return `<div class="organization-settings"><div class="settings-header"><div><h1 class="page-title">${esc(org?.name || 'Organization')}</h1>
    <p class="settings-intro">Organization settings</p></div><button class="btn sm" id="create-organization">＋ New organization</button></div>
    ${S.inviteNotice ? `<div class="card"><b>${esc(S.inviteNotice)}</b></div>` : ''}
    <div class="settings-layout">
    <nav class="settings-nav" aria-label="Settings sections"><span>Organization</span><a href="#settings-plan">Plan &amp; billing</a><a href="#settings-code">Projects</a><a href="#settings-compute">Where tasks run</a><a href="#settings-agents">Codex/Claude</a><a href="#settings-avatars">Avatars</a><a href="#settings-defaults">Task defaults</a><a href="#settings-payments">Passwords &amp; payments</a><a href="#settings-people">People &amp; authorization</a><a href="#settings-installation">Workflows</a><a href="#settings-advanced" data-settings-advanced hidden>Advanced</a></nav>
    <div class="settings-content">

    <div class="settings-section-title" id="settings-plan"><div>Plan &amp; billing<small>Current organization limits and hosted subscription</small></div></div>
    <div class="card" id="org-plan">Loading…</div>
    <div class="settings-section-title" id="settings-billing"><div>Subscription billing<small>Hosted subscription and active-user seats—not cards used by agents</small></div></div>
    <div class="card" id="org-subscription"><p class="task-sub">Loading verified subscription status…</p></div>

    <div class="settings-section-title" id="settings-people"><div>People &amp; authorization<small>Who is in this organization, and what each person may do</small></div></div>
    <div class="card"><div class="section-h">People</div><div id="org-members">Loading…</div>
      <div class="authz-invite-row"><input id="invite-email" placeholder="teammate@company.com">${authorizationEditorHtml('invite-authorization', { level: 'developer', scope: 'organization' }, authorizationProjects)}<button class="btn sm" id="invite-member">Invite</button></div><div id="invite-result" class="task-sub"></div>
      <div class="settings-divider"></div><div class="section-h">Teams</div><p class="task-sub">Teams are reusable review routes. A team named Leaders is available to workflows as <span class="mono">@team:leaders</span>.</p><div id="org-teams">Loading…</div><datalist id="org-people-options"></datalist><div class="inline-form"><input id="team-name" placeholder="Leaders"><button class="btn sm" id="create-team">Create team</button></div></div>
    <div class="settings-section-title" id="settings-code"><div>Projects<small>Repository access and storage shared by this organization’s projects</small></div></div>
    <div class="card"><div class="section-h">Git &amp; GitHub</div><div id="org-github">Loading…</div></div>
    <div class="card"><div class="section-h" id="settings-storage">Data storage</div><p class="task-sub">Where encrypted, versioned project Data revisions are retained.</p><div id="org-storage">Loading…</div></div>

    <div class="settings-section-title" id="settings-compute"><div>Where tasks run</div></div>
    <div class="card"><div class="section-h">Task execution</div><div id="org-execution">Loading…</div><div class="section-h" style="margin-top:22px">Cloud providers</div><div id="org-providers">Loading…</div><div class="section-h" style="margin-top:22px">Capacity &amp; usage</div><div id="org-usage">Loading…</div><div id="org-runners"></div></div>

    <div class="settings-section-title" id="settings-avatars"><div>Avatars<small>Organization-wide availability</small></div></div>
    ${AVATAR_RISK_NOTE}
    <div class="card"><div id="organization-avatar-settings">Loading…</div></div>

    ${globalSettingsView(true)}

    <div class="settings-section-title" id="settings-advanced" data-settings-advanced hidden><div>Advanced</div></div><div id="org-misc-slot"></div>
    <details class="card settings-disclosure" data-settings-access="organization" hidden><summary><b>Single sign-on &amp; directory sync</b><span>For organizations that already use an identity provider</span></summary><p class="task-sub">OIDC makes employees sign in through your company. SCIM automatically adds, removes, and groups them. Leave this untouched unless your identity administrator gives you these values.</p><div id="org-identity">Loading…</div></details>
    <div class="card data-export-card" data-settings-access="organization" hidden>
      <div class="data-export-mark" aria-hidden="true"><span>{ }</span><i></i></div>
      <div class="data-export-copy"><div class="section-h">Export organization data</div>
        <p class="task-sub">Download a readable JSON archive of this organization, grouped into complete record collections.</p>
        <p class="data-export-note">Passwords, tokens, and stored credentials are never included.</p></div>
      <button class="btn sm" id="export-organization" type="button">Export organization data</button>
    </div>
    <div class="card" data-settings-access="organization" hidden>
      <div class="section-h">Organization name</div>
      <div class="inline-form"><input id="organization-name" value="${esc(org?.name || '')}" aria-label="Organization name"><button class="btn sm primary" id="rename-organization">Save name</button>${org?.kind === 'team' ? '<button class="btn sm danger" id="delete-organization">Delete organization</button>' : ''}</div>
    </div>
    </div></div></div>`;
}

function pendingInvitationRow(invitation, projects) {
  const authorization = invitation.authorization || { level: invitation.profileId || 'developer', scope: 'organization' };
  return `<div class="member-row" data-invitation="${esc(invitation.id)}"><span>${esc(invitation.email)}</span><span class="chip">${esc(authorizationSummary(authorization, projects))}</span></div>`;
}

function organizationPlanMarkup(entitlements) {
  if (!entitlements) return '<span class="task-sub">Plan information is temporarily unavailable.</span>';
  if (entitlements.deployment === 'private') return `<div class="section-h">Private installation</div>
    <p class="task-sub">Hosted plan restrictions are not applied. Users, projects, and active agent runs are limited only by this installation’s own capacity settings.</p>`;
  const memberCount = Number(entitlements.currentMemberCount ?? entitlements.activeUsers ?? 0);
  const users = entitlements.maxMembers == null
    ? `${memberCount} active user${memberCount === 1 ? '' : 's'} · unlimited`
    : `${memberCount} of ${entitlements.maxMembers} user${entitlements.maxMembers === 1 ? '' : 's'}${entitlements.overMemberLimit ? ' · over limit' : ''}`;
  const projects = entitlements.unlimitedProjects ? 'Unlimited projects' : `${entitlements.maxProjects} projects`;
  const runs = `${entitlements.maxActiveAgentRuns} active agent run${entitlements.maxActiveAgentRuns === 1 ? '' : 's'}`;
  const monthly = Number(entitlements.currentMonthlyPriceCents || 0) / 100;
  const price = monthly ? `$${Number.isInteger(monthly) ? monthly : monthly.toFixed(2)}/month` : '$0/month';
  const usage = `${entitlements.activeAgentRuns || 0} active · ${entitlements.queuedAgentRuns || 0} queued`;
  const memberWarning = entitlements.overMemberLimit
    ? `<div class="card" style="padding:10px;border-color:var(--warn);margin:10px 0"><b>Agent runs are paused</b><div class="task-sub">${esc(entitlements.planName)} allows ${esc(entitlements.maxMembers)} organization user${entitlements.maxMembers === 1 ? '' : 's'}, but this organization has ${esc(memberCount)}. Remove ${esc(memberCount - entitlements.maxMembers)} extra member${memberCount - entitlements.maxMembers === 1 ? '' : 's'} in <a href="#settings-people">People &amp; authorization</a>, or restore Team. Running agents may finish; no new agent run will start until this is resolved.</div></div>`
    : '';
  return `<div class="section-h">${esc(entitlements.planName)} <span class="chip">${esc(price)}</span></div>
    ${memberWarning}
    <div class="settings-grid"><label class="form-row">People<input value="${esc(users)}" readonly></label><label class="form-row">Projects<input value="${esc(projects)}" readonly></label><label class="form-row">Agent concurrency<input value="${esc(runs)}" readonly></label><label class="form-row">Current agent usage<input value="${esc(usage)}" readonly></label></div>
    <p class="task-sub">Concurrency is a shared maximum for this organization. Work above the limit waits in queue; it is not reserved capacity.</p>`;
}

function appendPendingInvitation(invitation, projects) {
  const box = $('#pending-invitations');
  if (!box || !invitation) return;
  if ([...(box.querySelectorAll?.('[data-invitation]') || [])]
    .some((row) => row.dataset.invitation === invitation.id)) return;
  box.hidden = false;
  box.insertAdjacentHTML('beforeend', pendingInvitationRow(invitation, projects));
}

async function hydrateOrganizationView() {
  if (!$('#org-members') || !S.organizationId) return;
  const organizationId = S.organizationId;
  const epoch = S.organizationViewEpoch = (S.organizationViewEpoch || 0) + 1;
  const renderIsCurrent = () => S.organizationViewEpoch === epoch
    && S.organizationId === organizationId
    && !!$('#org-members');
  wireSettingsNavigation();
  hydrateSettingsAccess({ organizationId });
  hydrateAvatarAvailability('organization', organizationId);
  hydrateOrganizationSubscription(organizationId);
  await loadCollaboration().catch(() => {});
  if (!renderIsCurrent()) return;
  const userRecord = (id, embedded) => embedded || S.organizationMembers.find((member) => member.userId === id)?.user || S.users.find((user) => user.id === id);
  const userName = (id, embedded) => userRecord(id, embedded)?.name?.trim() || userRecord(id, embedded)?.email?.split('@')[0] || 'Unnamed member';
  const personChoice = (member) => { const user = userRecord(member.userId, member.user); const name = userName(member.userId, member.user); return user?.email ? `${name} — ${user.email}` : name; };
  const personMarkup = (id, embedded) => { const user = userRecord(id, embedded); return `<span class="person-name"><b>${esc(userName(id, embedded))}</b>${user?.email ? `<small>${esc(user.email)}</small>` : ''}</span>`; };
  const authorizationProjects = S.projects.filter((project) => project.organizationId === organizationId);
  $('#org-members').innerHTML = S.organizationMembers.length ? S.organizationMembers.map((m) => {
    const current = m.authorization || { level: m.profileId || 'viewer', scope: 'organization' };
    return `<div class="member-row authz-member-row" data-org-member="${esc(m.userId)}">${personMarkup(m.userId, m.user)}${m.protectedOwner ? '<span class="chip" title="Recovery ownership is protected; authorization remains editable">protected owner</span>' : ''}${authorizationEditorHtml(`org-authorization-${m.userId}`, current, authorizationProjects)}<button class="btn sm org-member-remove">Remove</button></div>`;
  }).join('') : '<span class="task-sub">No members.</span>';
  const [entitlements, gitConnections, githubApp, githubIdentity, runners, providerConnections, executionPolicy, usage, usagePolicy, identityPolicy, invitations, teamMembers, storageLocations] = await Promise.all([
    api(`/api/organizations/${organizationId}/entitlements`).catch(() => null),
    api(`/api/organizations/${organizationId}/git-connections`).catch(() => []),
    api(`/api/organizations/${organizationId}/github/app`).catch(() => ({ configured: false })),
    api(`/api/organizations/${organizationId}/github/identity`).catch(() => ({ profile: null })),
    api(`/api/organizations/${organizationId}/runner-pools`).catch(() => []),
    api(`/api/organizations/${organizationId}/world-providers`).catch(() => []),
    api(`/api/organizations/${organizationId}/execution-policy`).catch(() => ({ worldProvider: S.meta?.hosted ? 'e2b' : 'worktree', resources: { cpu: 2, memoryMb: 2048 }, network: { unrestricted: true }, hibernateAfterMs: 604800000 })),
    api(`/api/organizations/${organizationId}/usage`).catch(() => null),
    api(`/api/organizations/${organizationId}/usage-policy`).catch(() => null),
    api(`/api/organizations/${organizationId}/identity-policy`).catch(() => null),
    api(`/api/organizations/${organizationId}/invitations`).catch(() => []),
    Promise.all(S.teams.map((team) => api(`/api/organizations/${organizationId}/teams/${team.id}/members`).catch(() => []).then((members) => ({ team, members })))),
    api(`/api/organizations/${organizationId}/storage`).catch(() => []),
  ]);
  if (!renderIsCurrent()) return;
  $('#org-plan').innerHTML = organizationPlanMarkup(entitlements);
  const pendingInvitations = invitations.filter((invitation) => !invitation.acceptedAt);
  $('#org-members').insertAdjacentHTML('beforeend', `<div id="pending-invitations" ${pendingInvitations.length ? '' : 'hidden'}><div class="section-h" style="margin-top:12px">Pending invitations</div>${pendingInvitations.map((invitation) => pendingInvitationRow(invitation, authorizationProjects)).join('')}</div>`);
  $('#org-people-options').innerHTML = S.organizationMembers.map((member) => `<option value="${esc(personChoice(member))}"></option>`).join('');
  $('#org-teams').innerHTML = teamMembers.length ? teamMembers.map(({ team, members }) => `<div class="team-block" data-team="${esc(team.id)}"><div class="team-heading"><span><b>${esc(team.name)}</b><span class="task-sub mono">@team:${esc(team.slug)}</span></span><span class="team-actions"><span class="chip">${members.length} member${members.length === 1 ? '' : 's'}</span><button class="btn sm team-rename">Rename</button><button class="btn sm danger team-delete">Delete</button></span></div><div class="inline-form team-rename-form" hidden><input class="team-name-edit" value="${esc(team.name)}" aria-label="Team name"><button class="btn sm primary team-rename-save">Save name</button><button class="btn sm team-rename-cancel">Cancel</button></div>${members.map((m) => `<div class="member-row">${personMarkup(m.userId, m.user)}<button class="btn sm team-member-remove" data-user="${esc(m.userId)}">Remove</button></div>`).join('')}<div class="inline-form"><input class="team-user" list="org-people-options" autocomplete="off" placeholder="Type a name or email"><button class="btn sm team-member-add">Add person</button></div></div>`).join('') : '<span class="task-sub">No teams yet.</span>';
  const githubManageUrl = (connection) => connection.accountType === 'Organization'
    ? `https://github.com/organizations/${encodeURIComponent(connection.accountLogin)}/settings/installations/${encodeURIComponent(connection.installationId)}`
    : `https://github.com/settings/installations/${encodeURIComponent(connection.installationId)}`;
  const githubSetup = !githubApp.configured
    ? (S.installationAccess
      ? `<a class="btn primary" data-spa href="${installationRoute()}#installation-github">Set up GitHub for this installation</a>`
      : '<span class="task-sub">The installation operator must set up the shared GitHub App before this organization can connect repositories.</span>')
    : `<button class="btn ${gitConnections.length ? '' : 'primary'}" id="connect-github" type="button">${githubMark()}${gitConnections.length ? 'Add new GitHub account' : 'Connect GitHub'}</button>${gitConnections.length ? '<button class="btn" id="org-github-custom" type="button">Custom automation identity</button>' : ''}`;
  $('#org-github').innerHTML = `<div class="github-account-list">${gitConnections.map((connection) => {
    const permission = connection.permissionStatus;
    const permissionAction = permission?.ready ? '' : permission?.unavailable
      ? '<span class="chip" style="color:var(--warn)">access unknown</span>'
      : permission?.missingApp?.length
        ? `<a class="btn sm primary" href="${esc(permission?.appSettingsUrl || githubManageUrl(connection))}" target="_blank" rel="noopener noreferrer">Update App permissions</a>`
        : `<a class="btn sm primary" href="${esc(permission?.installationSettingsUrl || githubManageUrl(connection))}" target="_blank" rel="noopener noreferrer">Approve permissions</a>`;
    return `<div class="github-account-row" data-connection="${esc(connection.id)}">
    <span class="github-account-label">${githubMark()}<b>${esc(connection.accountLogin)}</b>${permission?.ready ? '' : '<span class="chip" style="color:var(--warn)">GitHub access update required</span>'}</span>
    <span class="github-account-actions">${permissionAction}<a class="btn sm" href="${esc(githubManageUrl(connection))}" target="_blank" rel="noopener noreferrer">Manage</a><button class="icon-btn github-remove" type="button" aria-label="Remove GitHub connection">${trashIcon()}</button></span>
  </div>`; }).join('')}</div>
  <div class="github-org-actions">${githubSetup}</div>`;
  const connectionFor = (provider) => providerConnections.find((connection) => connection.provider === provider);
  S.worldProviderConnections = providerConnections;
  // The default Agent environment moved to Task defaults (below) and can be
  // overridden per project/task. Compute keeps the runner pool + budget; the pool
  // list is scoped to the effective environment, shown read-only here.
  const orgEnvironment = executionPolicy.worldProvider || (S.meta?.hosted ? 'e2b' : 'worktree');
  $('#org-execution').innerHTML = `<div class="settings-grid">
    <label class="form-row">Agent environment<input value="${esc(orgEnvironment)}" disabled title="Set the default in Task defaults; override it per project or task" /></label>
    <label class="form-row">Default runner pool<select id="org-execution-pool"></select></label>
    <label class="form-row">World experience<select id="org-execution-flavor"><option value="headless" ${(executionPolicy.environment?.flavor || 'headless') === 'headless' ? 'selected' : ''}>Headless · coding + browser MCP</option><option value="desktop" ${executionPolicy.environment?.flavor === 'desktop' ? 'selected' : ''}>Desktop · adds GUI + noVNC</option></select></label>
    <label class="form-row">CPU per world<input id="org-execution-cpu" type="number" min="1" value="${esc(executionPolicy.resources?.cpu || 2)}" /></label>
    <label class="form-row">Memory per world (MiB)<input id="org-execution-memory" type="number" min="128" step="128" value="${esc(executionPolicy.resources?.memoryMb || 2048)}" /></label>
    <label class="form-row">Cloud budget (USD/month)<input id="org-execution-budget" type="number" min="0" step="0.01" value="${executionPolicy.monthlyBudgetMicros == null ? '' : esc(executionPolicy.monthlyBudgetMicros / 1e6)}" placeholder="Unlimited" /></label>
    <label class="form-row">Hibernate parked worlds after (days)<input id="org-execution-hibernate" type="number" min="1" value="${esc(Math.round((executionPolicy.hibernateAfterMs || 604800000) / 86400000))}" /></label>
    <label class="form-row">Outbound network<select id="org-execution-network"><option value="unrestricted" ${executionPolicy.network?.unrestricted !== false ? 'selected' : ''}>Normal internet access (recommended)</option><option value="restricted" ${executionPolicy.network?.unrestricted === false ? 'selected' : ''}>Restricted allowlist</option></select></label>
  </div>
  <p class="task-sub">Coding agents normally need arbitrary package registries, documentation, web search, and APIs. Restricted mode is for organizations with a maintained egress policy.</p>
  <details id="org-network-restrictions" ${executionPolicy.network?.unrestricted === false ? 'open' : ''}><summary class="task-sub">Restricted-network allowlist</summary><label class="form-row">Allowed domains<input id="org-execution-domains" value="${esc((executionPolicy.network?.allowDomains || []).join(', '))}" placeholder="registry.npmjs.org, pypi.org" /></label><label class="form-row">Allowed CIDRs<input id="org-execution-cidrs" value="${esc((executionPolicy.network?.allowCidrs || []).join(', '))}" placeholder="10.20.0.0/16" /></label></details>
  <button class="btn sm primary" id="org-execution-save">Save execution policy</button>`;
  const providerInfo = {
    e2b: { name: 'E2B', site: 'https://e2b.dev', keys: 'https://e2b.dev/dashboard?tab=keys' },
    daytona: { name: 'Daytona', site: 'https://www.daytona.io', keys: 'https://app.daytona.io' },
  };
  $('#org-providers').innerHTML = ['e2b', 'daytona'].map((provider) => {
    const connection = connectionFor(provider); const config = connection?.config || {};
    const state = connection ? `${connection.status}${connection.enabled ? '' : ' · disabled'}` : 'not connected';
    const info = providerInfo[provider];
    return `<div class="team-block provider-connection" data-provider="${provider}">
      <div class="member-row"><b>${info.name}</b><span class="chip">${esc(state)}</span>${connection ? '<button class="btn sm provider-test">Test</button><button class="btn sm provider-disconnect">Disconnect</button>' : ''}</div>
      <p class="task-sub">No account yet? Create one at <a href="${info.site}" target="_blank" rel="noopener noreferrer">${esc(info.site.replace(/^https?:\/\//, ''))}</a>, then paste an <a href="${info.keys}" target="_blank" rel="noopener noreferrer">API key</a> below.</p>
      ${connection?.lastError ? `<p class="task-sub" style="color:var(--danger)">${esc(connection.lastError)}</p>` : ''}
      <div class="settings-grid"><label class="form-row">API key<input class="provider-key" type="password" autocomplete="new-password" placeholder="${connection ? 'Leave blank to keep current key' : 'Required'}" /></label>
      ${provider === 'e2b' ? `<label class="form-row">Headless template<input class="provider-template" value="${esc(config.template || '')}" placeholder="codex" /></label><label class="form-row">Desktop template<input class="provider-desktop-template" value="${esc(config.desktopTemplate || '')}" placeholder="desktop" /></label>`
        : `<label class="form-row">Headless snapshot<input class="provider-snapshot" value="${esc(config.snapshot || '')}" placeholder="recommended" /></label><label class="form-row">Headless image<input class="provider-image" value="${esc(config.image || '')}" placeholder="used only when snapshot is blank" /></label><label class="form-row">Desktop snapshot<input class="provider-desktop-snapshot" value="${esc(config.desktopSnapshot || '')}" placeholder="Daytona default when blank" /></label><label class="form-row">Desktop image<input class="provider-desktop-image" value="${esc(config.desktopImage || '')}" placeholder="used only when desktop snapshot is blank" /></label><label class="form-row">API URL<input class="provider-api-url" value="${esc(config.apiUrl || '')}" placeholder="https://app.daytona.io/api" /></label><label class="form-row">Target<input class="provider-target" value="${esc(config.target || '')}" placeholder="provider default" /></label>`}
      </div><button class="btn sm primary provider-save">${connection ? 'Save & verify' : 'Connect & verify'}</button></div>`;
  }).join('');
  $('#org-runners').innerHTML = `${runners.map((r) => `<div class="member-row" data-runner="${esc(r.id)}"><span>${esc(r.name)}</span><span class="chip">${esc(r.provider)} · ${hostLocal() ? `${r.capacity.activeWorlds} worlds` : `concurrency capacity ${usagePolicy?.maxActiveWorlds || r.capacity.activeWorlds}`}</span>${r.id.includes(':managed-') ? '' : '<button class="btn sm runner-delete">Delete</button>'}</div>`).join('')}
    <div class="inline-form"><input id="runner-name" placeholder="Dedicated pool"><select id="runner-provider"><option value="e2b">E2B</option><option value="daytona">Daytona</option></select>${hostLocal() ? '<input id="runner-worlds" type="number" min="1" value="20" title="Concurrent worlds">' : ''}<button class="btn sm" id="runner-create">Add pool</button></div>`;
  $('#org-storage').innerHTML = `<div class="project-help-callout"><span class="callout-mark">i</span><div><b>Managed storage is intentionally bounded.</b> Connect your own bucket for large versioned datasets. For live or frequently changing data, add the bucket as a project Service instead of copying it into krmax.</div></div>
    ${storageLocations.map((location) => { const usage = location.usage || {}; const pct = usage.quotaBytes ? Math.min(100, usage.retainedBytes / usage.quotaBytes * 100) : 0; return `<div class="team-block storage-location" data-storage="${esc(location.id)}"><div class="member-row"><span><b>${esc(location.name)}</b> <span class="chip">${location.kind === 'managed' ? 'managed' : 'customer S3'}</span> ${location.isDefault ? '<span class="chip">default</span>' : ''}</span><span>${formatBytes(usage.retainedBytes || 0)}${usage.quotaBytes ? ` / ${formatBytes(usage.quotaBytes)}` : ''}</span>${!location.isDefault && location.status === 'ready' ? '<button class="btn sm storage-default">Make default</button>' : ''}${location.kind === 's3' ? '<button class="btn sm storage-test">Test</button><button class="btn sm danger storage-delete">Remove</button>' : ''}</div>${usage.quotaBytes ? `<div class="progress"><i style="width:${pct}%"></i></div>` : ''}${location.config?.bucket ? `<p class="task-sub mono">${esc(location.config.endpoint)}/${esc(location.config.bucket)}/${esc(location.config.prefix || '')}</p>` : ''}${location.lastError ? `<p class="task-sub" style="color:var(--danger)">${esc(location.lastError)}</p>` : ''}</div>`; }).join('')}
    <details class="settings-disclosure compact"><summary><b>Connect customer-owned S3 storage</b></summary><div class="settings-grid">
      <label class="form-row">Name<input id="storage-name" placeholder="Production data"></label><label class="form-row">Endpoint<input id="storage-endpoint" placeholder="https://s3.amazonaws.com"></label>
      <label class="form-row">Bucket<input id="storage-bucket" placeholder="company-karmax"></label><label class="form-row">Region<input id="storage-region" value="us-east-1"></label>
      <label class="form-row">Restricted prefix<input id="storage-prefix" value="karmax/${esc(organizationId)}"></label><label class="form-row">Access key ID<input id="storage-access-key" autocomplete="off"></label>
      <label class="form-row">Secret access key<input id="storage-secret-key" type="password" autocomplete="new-password"></label></div>
      <p class="task-sub">Use a dedicated bucket policy restricted to this prefix. Credentials are encrypted in the krmax vault and never returned by the API.</p><button class="btn sm primary" id="storage-connect">Connect &amp; test</button></details>`;
  const usageSync = (usage?.sync || []).filter((item) => item.provider === 'e2b');
  const usageSyncLabel = usageSync.some((item) => item.status === 'error') ? ' · sync unavailable'
    : usageSync.some((item) => item.status === 'pending') ? ' · first sync pending'
      : usageSync.length ? ` · synced ${fmtAgo(Math.max(...usageSync.map((item) => Number(item.at || 0))))}` : '';
  const coverageFrom = usageSync.length ? Math.max(...usageSync.map((item) => Number(item.coverageFrom || 0))) : 0;
  const usagePeriod = usageSync.some((item) => item.gap) ? 'Incomplete history'
    : coverageFrom > Number(usage?.from || 0)
      ? `Since ${new Date(coverageFrom).toLocaleDateString([], { month: 'short', day: 'numeric' })}` : 'This month';
  const usageFunding = usage?.byFundingSource || {};
  $('#org-usage').innerHTML = usage ? `<div class="stat"><div class="n">$${(usage.costMicros / 1e6).toFixed(2)}</div><div class="l">Metered + estimated usage · ${usagePeriod} · ${usage.events} ledger events${usageSyncLabel}</div></div>
    <p class="task-sub">Incurred $${((usage.incurredCostMicros || 0) / 1e6).toFixed(2)} · estimated $${((usage.estimatedCostMicros || 0) / 1e6).toFixed(2)} · active managed reservations $${((usage.activeReservationsMicros || 0) / 1e6).toFixed(2)}</p>
    <p class="task-sub">Managed $${((usageFunding.managed || 0) / 1e6).toFixed(2)} (${usage.requests?.managed || 0} model requests) · BYOK $${((usageFunding.byok || 0) / 1e6).toFixed(2)} (${usage.requests?.byok || 0} model requests) · active: ${usage.active?.agentTurns || 0} model turns, ${usage.active?.worlds || 0} worlds, ${usage.active?.executions || 0} commands</p>
    ${usagePolicy ? `<details class="settings-disclosure compact"><summary><b>Usage guardrails</b></summary><div class="settings-grid">
      <label class="form-row">Managed spend cap (USD/month)<input id="usage-managed-cap" type="number" min="0.01" step="0.01" value="${usagePolicy.managedSpendCapMicros == null ? '' : esc(usagePolicy.managedSpendCapMicros / 1e6)}" placeholder="Disabled" /></label>
      <label class="form-row">Managed model providers<input id="usage-managed-providers" value="${esc((usagePolicy.managedModelProviders || []).join(', '))}" placeholder="Disabled" /></label>
      <label class="form-row">Allowed model providers<input id="usage-allowed-providers" value="${esc((usagePolicy.allowedModelProviders || []).join(', '))}" placeholder="All connected BYOK providers" /></label>
      <label class="form-row">Allowed models<input id="usage-allowed-models" value="${esc((usagePolicy.allowedModels || []).join(', '))}" placeholder="All models" /></label>
      <label class="form-row">Model starts / minute<input id="usage-agent-rate" type="number" min="1" value="${esc(usagePolicy.maxAgentStartsPerMinute)}" /></label>
      <label class="form-row">Sandbox starts / minute<input id="usage-world-rate" type="number" min="1" value="${esc(usagePolicy.maxRemoteStartsPerMinute)}" /></label>
      <label class="form-row">Optional tighter model concurrency<input id="usage-agent-active" type="number" min="1" max="${esc(entitlements?.maxActiveAgentRuns || 1000000)}" value="${usagePolicy.maxActiveAgentTurns == null ? '' : esc(usagePolicy.maxActiveAgentTurns)}" placeholder="Plan limit: ${esc(usagePolicy.effectiveMaxActiveAgentTurns)}" /></label>
      ${hostLocal() ? `<label class="form-row">Concurrent remote worlds<input id="usage-world-active" type="number" min="1" value="${esc(usagePolicy.maxActiveWorlds)}" /></label>`
        : `<div class="form-row"><span>Concurrent remote worlds</span><b>Same as agent concurrency: ${esc(usagePolicy.maxActiveWorlds)}</b></div>`}
    </div><p class="task-sub">The plan admits ${esc(entitlements?.maxActiveAgentRuns || usagePolicy.effectiveMaxActiveAgentTurns)} shared active agent runs; an owner may only set a tighter cap here. Managed model use is off until an owner sets a spend cap and explicitly enables a provider. BYOK remains separately attributed. Remote sandboxes use the organization’s own provider account.</p><button class="btn sm primary" id="usage-policy-save">Save usage guardrails</button></details>` : ''}` : 'Usage unavailable.';
  if (identityPolicy) $('#org-identity').innerHTML = `<label class="form-row">OIDC provider ID<input id="oidc-provider" value="${esc(identityPolicy.oidcProviderId || S.sso?.providerId || '')}" /></label>
    <label class="form-row">Verified email domains<input id="identity-domains" value="${esc((identityPolicy.verifiedDomains || []).join(', '))}" placeholder="company.com" /></label>
    <label class="switch"><input id="enforce-sso" type="checkbox" ${identityPolicy.enforceSso ? 'checked' : ''}/>Require SSO for this organization</label>
    <div class="inline-form"><button class="btn sm primary" id="save-identity">Save policy</button><button class="btn sm" id="rotate-scim">Rotate SCIM token</button></div>
    <div id="scim-result" class="task-sub">SCIM base URL: <span class="mono">${esc(location.origin)}/scim/v2/${esc(S.organizationId)}</span></div>`;
  wireAuthorizationEditor($('#invite-authorization'), authorizationProjects);
  $('#invite-member')?.addEventListener('click', async () => {
    try {
      const email = $('#invite-email').value;
      const result = await api(`/api/organizations/${S.organizationId}/invitations`, { method: 'POST', body: JSON.stringify({ email, authorization: readAuthorizationEditor($('#invite-authorization')) }) });
      const link = `${location.origin}/invite?token=${encodeURIComponent(result.token)}`;
      $('#invite-result').innerHTML = result.emailed ? `Invitation emailed to <b>${esc(email)}</b>. <span class="task-sub">You can also share this link:</span><br><span class="mono">${esc(link)}</span>` : `Copy this one-time invitation link:<br><span class="mono">${esc(link)}</span>`;
      appendPendingInvitation(result.invitation, authorizationProjects);
      $('#invite-email').value = '';
    } catch (e) { toast(e.message, true); }
  });
  $('#create-team')?.addEventListener('click', async () => { try { await api(`/api/organizations/${S.organizationId}/teams`, { method: 'POST', body: JSON.stringify({ name: $('#team-name').value }) }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } });
  $('#connect-github')?.addEventListener('click', async () => {
    try {
      const result = await api(`/api/organizations/${S.organizationId}/github/install-url`, { method: 'POST', body: '{}' });
      location.assign(result.url);
    } catch (error) { toast(error.message, true); }
  });
  $('#org-github-custom')?.addEventListener('click', () => openGitIdentityDialog({
    title: 'Custom automation identity', profile: githubIdentity.profile,
    endpoint: `/api/organizations/${S.organizationId}/github/identity`, onSaved: hydrateOrganizationView,
  }));
  $('#org-github').querySelectorAll('.github-account-row').forEach((row) => {
    row.querySelector('.github-remove')?.addEventListener('click', async () => {
      try { await api(`/api/organizations/${S.organizationId}/git-connections/${encodeURIComponent(row.dataset.connection)}`, { method: 'DELETE' }); await hydrateOrganizationView(); }
      catch (error) { toast(error.message, true); }
    });
  });
  $('#org-providers').querySelectorAll('.provider-connection').forEach((row) => {
    const provider = row.dataset.provider;
    row.querySelector('.provider-save')?.addEventListener('click', async () => {
      const body = { apiKey: row.querySelector('.provider-key').value || undefined, config: provider === 'e2b'
        ? { template: row.querySelector('.provider-template').value, desktopTemplate: row.querySelector('.provider-desktop-template').value }
        : { snapshot: row.querySelector('.provider-snapshot').value, image: row.querySelector('.provider-image').value,
            desktopSnapshot: row.querySelector('.provider-desktop-snapshot').value, desktopImage: row.querySelector('.provider-desktop-image').value,
            apiUrl: row.querySelector('.provider-api-url').value, target: row.querySelector('.provider-target').value } };
      try { await api(`/api/organizations/${S.organizationId}/world-providers/${provider}`, { method: 'PUT', body: JSON.stringify(body) }); await api(`/api/organizations/${S.organizationId}/world-providers/${provider}/test`, { method: 'POST', body: '{}' }); toast(`${provider === 'e2b' ? 'E2B' : 'Daytona'} connected`); await hydrateOrganizationView(); }
      catch (e) { toast(e.message, true); await hydrateOrganizationView(); }
    });
    row.querySelector('.provider-test')?.addEventListener('click', async () => { try { await api(`/api/organizations/${S.organizationId}/world-providers/${provider}/test`, { method: 'POST', body: '{}' }); toast('Connection verified'); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); await hydrateOrganizationView(); } });
    row.querySelector('.provider-disconnect')?.addEventListener('click', async () => { if (!confirm(`Disconnect ${provider}? Existing task worlds must be removed first.`)) return; try { await api(`/api/organizations/${S.organizationId}/world-providers/${provider}`, { method: 'DELETE' }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } });
  });
  $('#storage-connect')?.addEventListener('click', async () => {
    try {
      const created = await api(`/api/organizations/${organizationId}/storage`, { method: 'POST', body: JSON.stringify({
        name: $('#storage-name').value, endpoint: $('#storage-endpoint').value, bucket: $('#storage-bucket').value,
        region: $('#storage-region').value, prefix: $('#storage-prefix').value,
        accessKeyId: $('#storage-access-key').value, secretAccessKey: $('#storage-secret-key').value,
      }) });
      await api(`/api/organizations/${organizationId}/storage/${encodeURIComponent(created.id)}/test`, { method: 'POST', body: '{}' });
      toast('Customer storage connected'); await hydrateOrganizationView();
    } catch (error) { toast(error.message, true); }
  });
  $('#org-storage')?.querySelectorAll('[data-storage]').forEach((row) => {
    const id = encodeURIComponent(row.dataset.storage);
    row.querySelector('.storage-test')?.addEventListener('click', async () => { try {
      await api(`/api/organizations/${organizationId}/storage/${id}/test`, { method: 'POST', body: '{}' }); toast('Storage connection verified'); await hydrateOrganizationView();
    } catch (error) { toast(error.message, true); await hydrateOrganizationView(); } });
    row.querySelector('.storage-default')?.addEventListener('click', async () => { try {
      await api(`/api/organizations/${organizationId}/storage/${id}/default`, { method: 'PUT', body: '{}' }); toast('Default storage updated'); await hydrateOrganizationView();
    } catch (error) { toast(error.message, true); } });
    row.querySelector('.storage-delete')?.addEventListener('click', async () => {
      if (!confirm('Remove this storage connection? It is allowed only when no resource or revision uses it.')) return;
      try { await api(`/api/organizations/${organizationId}/storage/${id}`, { method: 'DELETE' }); await hydrateOrganizationView(); }
      catch (error) { toast(error.message, true); }
    });
  });
  $('#runner-create')?.addEventListener('click', async () => { try { const worlds = $('#runner-worlds')?.value; await api(`/api/organizations/${S.organizationId}/runner-pools`, { method: 'POST', body: JSON.stringify({ name: $('#runner-name').value, provider: $('#runner-provider').value, ...(worlds == null ? {} : { capacity: { activeWorlds: Number(worlds) } }) }) }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } });
  const matchingOrgPools = runners.filter((pool) => pool.provider === orgEnvironment && pool.enabled);
  $('#org-execution-pool').innerHTML = `<option value="">Organization BYOK default</option>${matchingOrgPools.map((pool) => `<option value="${esc(pool.id)}" ${pool.id === (executionPolicy.runnerPoolId || '') ? 'selected' : ''}>${esc(pool.name)}</option>`).join('')}`;
  $('#org-execution-network')?.addEventListener('change', (event) => { $('#org-network-restrictions').open = event.target.value === 'restricted'; });
  $('#org-execution-save')?.addEventListener('click', async () => {
    const split = (selector) => $(selector).value.split(',').map((value) => value.trim()).filter(Boolean);
    const restricted = $('#org-execution-network').value === 'restricted'; const budget = $('#org-execution-budget').value.trim();
    try {
      await api(`/api/organizations/${S.organizationId}/execution-policy`, { method: 'PUT', body: JSON.stringify({ policy: {
        runnerPoolId: $('#org-execution-pool').value || undefined,
        environment: { flavor: $('#org-execution-flavor').value },
        resources: { cpu: Number($('#org-execution-cpu').value), memoryMb: Number($('#org-execution-memory').value) },
        network: restricted ? { unrestricted: false, allowDomains: split('#org-execution-domains'), allowCidrs: split('#org-execution-cidrs') } : { unrestricted: true },
        monthlyBudgetMicros: budget === '' ? null : Math.round(Number(budget) * 1e6),
        hibernateAfterMs: Math.round(Number($('#org-execution-hibernate').value) * 86400000),
      } }) }); toast('Organization execution policy saved'); await hydrateOrganizationView();
    } catch (error) { toast(error.message, true); }
  });
  $('#usage-policy-save')?.addEventListener('click', async () => {
    const list = (selector) => $(selector).value.split(',').map((value) => value.trim()).filter(Boolean);
    const cap = $('#usage-managed-cap').value.trim();
    const agentCap = $('#usage-agent-active').value.trim();
    try {
      const policy = {
        managedSpendCapMicros: cap === '' ? null : Math.round(Number(cap) * 1e6),
        managedModelProviders: list('#usage-managed-providers'), allowedModelProviders: list('#usage-allowed-providers'),
        allowedModels: list('#usage-allowed-models'), maxAgentStartsPerMinute: Number($('#usage-agent-rate').value),
        maxRemoteStartsPerMinute: Number($('#usage-world-rate').value),
        maxActiveAgentTurns: agentCap === '' ? null : Number(agentCap),
        ...(hostLocal() ? { maxActiveWorlds: Number($('#usage-world-active').value) } : {}),
      };
      await api(`/api/organizations/${S.organizationId}/usage-policy`, { method: 'PUT', body: JSON.stringify({ policy }) }); toast('Usage guardrails saved'); await hydrateOrganizationView();
    } catch (error) { toast(error.message, true); }
  });
  $('#org-runners').querySelectorAll('[data-runner]').forEach((row) => row.querySelector('.runner-delete')?.addEventListener('click', async () => { if (!confirm('Delete this runner pool?')) return; try { await api(`/api/organizations/${S.organizationId}/runner-pools/${encodeURIComponent(row.dataset.runner)}`, { method: 'DELETE' }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } }));
  $('#save-identity')?.addEventListener('click', async () => { try { await api(`/api/organizations/${S.organizationId}/identity-policy`, { method: 'PUT', body: JSON.stringify({ oidcProviderId: $('#oidc-provider').value.trim(), verifiedDomains: $('#identity-domains').value.split(',').map((x) => x.trim()).filter(Boolean), enforceSso: $('#enforce-sso').checked }) }); toast('Identity policy saved'); } catch (e) { toast(e.message, true); } });
  $('#rotate-scim')?.addEventListener('click', async () => { try { const result = await api(`/api/organizations/${S.organizationId}/scim-token`, { method: 'POST', body: '{}' }); $('#scim-result').innerHTML = `Copy this token now; it is stored only as a hash:<br><span class="mono">${esc(result.token)}</span>`; } catch (e) { toast(e.message, true); } });
  $('#create-organization')?.addEventListener('click', createOrganization);
  $('#org-members')?.querySelectorAll('[data-org-member]').forEach((row) => {
    const editor = row.querySelector('.authz-editor');
    wireAuthorizationEditor(editor, authorizationProjects, async (authorization) => {
      if (authorization.scope === 'projects' && !authorization.projectIds?.length) return;
      try { await api(`/api/organizations/${S.organizationId}/members`, { method: 'POST', body: JSON.stringify({ userId: row.dataset.orgMember, authorization }) }); }
      catch (e) { toast(e.message, true); await hydrateOrganizationView(); }
    });
    row.querySelector('.org-member-remove')?.addEventListener('click', async () => { if (!confirm('Remove this member from the organization?')) return; try { await api(`/api/organizations/${S.organizationId}/members/${encodeURIComponent(row.dataset.orgMember)}`, { method: 'DELETE' }); await loadCollaboration(); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } });
  });
  $('#org-teams')?.querySelectorAll('[data-team]').forEach((block) => {
    block.querySelector('.team-member-add')?.addEventListener('click', async () => {
      const entered = block.querySelector('.team-user')?.value.trim();
      const member = S.organizationMembers.find((candidate) => personChoice(candidate).toLowerCase() === entered?.toLowerCase()
        || userName(candidate.userId, candidate.user).toLowerCase() === entered?.toLowerCase()
        || userRecord(candidate.userId, candidate.user)?.email?.toLowerCase() === entered?.toLowerCase());
      if (!member) return toast('Choose a person in this organization', true);
      try { await api(`/api/organizations/${S.organizationId}/teams/${block.dataset.team}/members`, { method: 'POST', body: JSON.stringify({ userId: member.userId }) }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); }
    });
    block.querySelector('.team-rename')?.addEventListener('click', () => { const form = block.querySelector('.team-rename-form'); form.hidden = false; form.querySelector('.team-name-edit').focus(); form.querySelector('.team-name-edit').select(); });
    block.querySelector('.team-rename-cancel')?.addEventListener('click', () => { block.querySelector('.team-rename-form').hidden = true; });
    block.querySelector('.team-rename-save')?.addEventListener('click', async () => {
      const name = block.querySelector('.team-name-edit')?.value.trim(); if (!name) return toast('Team name is required', true);
      try { await api(`/api/organizations/${S.organizationId}/teams/${block.dataset.team}`, { method: 'PATCH', body: JSON.stringify({ name }) }); await loadCollaboration(); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); }
    });
    block.querySelector('.team-name-edit')?.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); block.querySelector('.team-rename-save').click(); } if (event.key === 'Escape') block.querySelector('.team-rename-cancel').click(); });
    block.querySelector('.team-delete')?.addEventListener('click', async () => {
      const team = S.teams.find((candidate) => candidate.id === block.dataset.team);
      if (!confirm(`Delete “${team?.name || 'this team'}”? This is only allowed when no project or workflow still uses it.`)) return;
      try { await api(`/api/organizations/${S.organizationId}/teams/${block.dataset.team}`, { method: 'DELETE' }); await loadCollaboration(); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); }
    });
    block.querySelectorAll('.team-member-remove').forEach((button) => button.addEventListener('click', async () => { try { await api(`/api/organizations/${S.organizationId}/teams/${block.dataset.team}/members/${encodeURIComponent(button.dataset.user)}`, { method: 'DELETE' }); await hydrateOrganizationView(); } catch (e) { toast(e.message, true); } }));
  });
  $('#export-organization')?.addEventListener('click', () => location.assign(`/api/organizations/${encodeURIComponent(S.organizationId)}/export`));
  const renameOrganization = async () => {
    const name = $('#organization-name')?.value.trim();
    if (!name) return toast('Organization name is required', true);
    try {
      await api(`/api/organizations/${S.organizationId}`, { method: 'PATCH', body: JSON.stringify({ name }) });
      await loadOrganizations();
      toast('Organization renamed');
      renderShell();
      renderMain();
    } catch (e) { toast(e.message, true); }
  };
  $('#rename-organization')?.addEventListener('click', renameOrganization);
  $('#organization-name')?.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') { event.preventDefault(); renameOrganization(); }
  });
  $('#delete-organization')?.addEventListener('click', async () => { const org = S.organizations.find((o) => o.id === S.organizationId); const slug = prompt(`Type ${org?.slug} to permanently delete this organization`); if (!slug) return; try { await api(`/api/organizations/${S.organizationId}`, { method: 'DELETE', body: JSON.stringify({ confirmSlug: slug }) }); location.href = '/'; } catch (e) { toast(e.message, true); } });
}

async function createOrganization() {
  const name = prompt('Organization name');
  if (!name) { if ($('#org-switcher')) $('#org-switcher').value = S.organizationId; return; }
  try {
    const organization = await api('/api/organizations', { method: 'POST', body: JSON.stringify({ name }) });
    await loadOrganizations();
    S.organizationId = organization.id;
    S.projectId = null;
    await loadCollaboration().catch(() => {});
    await refreshOnboarding();
    renderShell();
    await go(globalRoute('organization'));
  } catch (error) { toast(error.message, true); if ($('#org-switcher')) $('#org-switcher').value = S.organizationId; }
}

// ── theme ────────────────────────────────────────────────────────────────────
function toggleTheme() {
  const cur = document.documentElement.getAttribute('data-theme');
  const next = cur === 'dark' ? 'light' : cur === 'light' ? '' : 'dark';
  if (next) document.documentElement.setAttribute('data-theme', next);
  else document.documentElement.removeAttribute('data-theme');
  localStorage.setItem('karmax-theme', next);
}
(function initTheme() {
  const t = localStorage.getItem('karmax-theme');
  if (t) document.documentElement.setAttribute('data-theme', t);
})();

// ── projects ─────────────────────────────────────────────────────────────────
// `folder` (from a folder row's "+") pre-fills the path so the new project
// lands in that folder; the person can still retype it into any other place.
function newProject(options) {
  const folder = options?.folder || '';
  const opener = document.activeElement;
  const host = document.createElement('div');
  host.innerHTML = `<div class="modal-overlay"><form class="modal-card new-project-dialog" role="dialog" aria-modal="true" aria-labelledby="new-project-title">
    <div class="new-project-head"><div><b id="new-project-title">New project</b><span>Use slashes to organize it into folders.</span></div><button class="icon-btn new-project-close" type="button" aria-label="Close">×</button></div>
    <label class="form-row"><span>Project name</span><input id="new-project-name" placeholder="e.g. Work/Clients/Website" required autocomplete="off" spellcheck="false" value="${esc(folder ? `${folder}/` : '')}"></label>
    <div class="new-project-preview" aria-live="polite">The final segment is the project name; everything before it becomes its sidebar folder.</div>
    <div class="form-error new-project-error" role="alert" hidden></div>
    <div class="new-project-actions"><button class="btn new-project-cancel" type="button">Cancel</button><button class="btn primary" type="submit">Create project</button></div>
  </form></div>`;
  const controller = new AbortController();
  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    controller.abort();
    document.removeEventListener('keydown', keydown);
    host.remove();
    opener?.focus?.();
  };
  const keydown = (event) => { if (event.key === 'Escape') close(); };
  host.querySelector('.modal-overlay').addEventListener('mousedown', (event) => { if (event.target === event.currentTarget) close(); });
  host.querySelector('.new-project-close').addEventListener('click', close);
  host.querySelector('.new-project-cancel').addEventListener('click', close);
  host.querySelector('form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = host.querySelector('#new-project-name').value.trim();
    const error = host.querySelector('.new-project-error');
    const button = event.submitter;
    if (!name) return;
    error.hidden = true;
    if (button) { button.disabled = true; button.textContent = 'Creating…'; }
    try {
      // Create with an EMPTY config so every field inherits from global settings.
      const endpoint = S.organizationId ? `/api/organizations/${encodeURIComponent(S.organizationId)}/projects` : '/api/projects';
      const project = await api(endpoint, { method: 'POST', body: JSON.stringify({ name, config: {} }), signal: controller.signal });
      if (closed) return;
      document.removeEventListener('keydown', keydown);
      host.remove();
      closed = true;
      await loadProjects();
      // A fresh project has no tasks, so Project settings remains the useful landing.
      await go(projectRoute(project.id, 'settings'));
    } catch (cause) {
      if (closed || cause?.name === 'AbortError') return;
      error.textContent = cause.message;
      error.hidden = false;
      if (button) { button.disabled = false; button.textContent = 'Create project'; }
      host.querySelector('#new-project-name').focus();
    }
  });
  $('#modal-root').appendChild(host);
  document.addEventListener('keydown', keydown);
  const input = host.querySelector('#new-project-name');
  input.focus();
  input.setSelectionRange(input.value.length, input.value.length); // type the name right after the folder path
}

// ── keyboard navigation / command registry (SPEC §10.1) ─────────────────────
// ONE registry feeds three views: key dispatch, the ⌘K palette, and the "?"
// help overlay — so they can never drift apart. Commands come from three tiers:
//   1. host commands — the console's own navigation + interaction grammar;
//   2. server-declared commands (GET /api/contributions): workflow packages
//      contribute `task.<action>` commands with default keybindings, and the
//      host maps them GENERICALLY onto the selected task's declared actions —
//      the host never hardcodes a workflow's action vocabulary;
//   3. the declared actions themselves (the auto-render floor, SPEC §10.2): every
//      enabled action of the selected task is a palette entry, and digits 1–9
//      press the task page's action buttons — so a workflow that declares no
//      keybindings at all is still fully keyboard-operable.

// -- keybinding strings ('meta+k', 'g t', '?', 'J') → step sequences ----------
const KEY_NAMES = { esc: 'escape', return: 'enter', up: 'arrowup', down: 'arrowdown', left: 'arrowleft', right: 'arrowright', cmd: 'meta', mod: 'meta' };
function parseKeybinding(binding) {
  return String(binding || '').trim().split(/\s+/).filter(Boolean).map((step) => {
    const parts = step.split('+').filter(Boolean);
    const raw = parts.pop() || '+'; // 'meta++' → the '+' key
    // single chars stay case-sensitive ('J' means shift+j); named keys normalize
    const key = raw.length === 1 ? raw : (KEY_NAMES[raw.toLowerCase()] || raw.toLowerCase());
    const out = { key };
    for (const p of parts) {
      const m = KEY_NAMES[p.toLowerCase()] || p.toLowerCase();
      if (m === 'meta') out.meta = true;
      else if (m === 'ctrl') out.ctrl = true;
      else if (m === 'alt') out.alt = true;
      else if (m === 'shift') out.shift = true;
    }
    return out;
  });
}
// Does a keydown (or a stored snapshot of one) match a binding step? 'meta'
// accepts Ctrl too (Linux/Windows); bare steps refuse held modifiers so Ctrl+C
// (copy) can never trigger a plain-'c' command.
function stepMatches(step, e) {
  const key = e.key.length === 1 ? e.key : e.key.toLowerCase();
  if (key !== step.key) return false;
  if (!!step.alt !== !!e.altKey) return false;
  if (step.meta) return !!(e.metaKey || e.ctrlKey);
  if (step.ctrl) return !!e.ctrlKey && !e.metaKey;
  return !e.metaKey && !e.ctrlKey;
}
// Which commands could still match after `pending` steps, given keystroke `snap`?
// Pure (unit-tested in web/keynav.test.cjs); `cmds` carry parsed `keys`.
function chordCandidates(cmds, pending, snap) {
  return cmds.filter((c) => {
    if (!c.keys || c.keys.length <= pending.length) return false;
    if (!pending.every((p, i) => stepMatches(c.keys[i], p))) return false;
    return stepMatches(c.keys[pending.length], snap);
  });
}
// Human-readable keybinding for chips ('meta+k' → ⌘K / Ctrl+K).
function fmtKeys(binding) {
  const mac = /Mac|iP/.test((typeof navigator !== 'undefined' && navigator.platform) || '');
  const NAME = { escape: 'Esc', enter: '↵', arrowup: '↑', arrowdown: '↓', arrowleft: '←', arrowright: '→', ' ': 'Space' };
  return parseKeybinding(binding)
    .map((s) => `${s.ctrl ? 'Ctrl+' : ''}${s.alt ? (mac ? '⌥' : 'Alt+') : ''}${s.meta ? (mac ? '⌘' : 'Ctrl+') : ''}${s.shift ? '⇧' : ''}${NAME[s.key] || s.key}`)
    .join(' ');
}
// Subsequence fuzzy match: score (higher = better), or -1 for no match.
function fuzzyScore(q, s) {
  if (!q) return 0;
  const hay = String(s).toLowerCase();
  let score = 0, at = 0, run = 0;
  for (const ch of String(q).toLowerCase()) {
    const idx = hay.indexOf(ch, at);
    if (idx < 0) return -1;
    run = idx === at && at > 0 ? run + 1 : 1;
    score += run * 2 + (idx === 0 || /[\s\-_./:]/.test(hay[idx - 1]) ? 3 : 0) - Math.min(idx - at, 6) * 0.5;
    at = idx + 1;
  }
  return score;
}

// -- the assembled registry ---------------------------------------------------
// Host commands. `key` is only the fallback — the binding of record comes from
// the server's command registry (S.contributions), so packages can rebind ids.
const HOST_COMMANDS = [
  { id: 'nav.commandPalette', title: 'Command palette', key: 'meta+k', run: () => openPalette() },
  { id: 'nav.globalSearch', title: 'Search everything', key: 'meta+shift+F', run: () => openGlobalSearch() },
  { id: 'help.keyboard', title: 'Keyboard shortcuts', key: '?', run: () => openHelp() },
  { id: 'nav.newTask', title: 'New task (quick add)', key: 'n', run: () => { switchTab('tasks'); setTimeout(() => $('#new-task')?.focus(), 30); } },
  { id: 'nav.newTaskForm', title: 'New task (full form)', key: 'N', run: () => { switchTab('tasks'); openTaskForm(QUICK_TASK_WORKFLOW, undefined, $('#new-task')?.value.trim()); } },
  { id: 'nav.search', title: 'Search tasks', key: '/', run: () => { if (S.tab !== 'tasks') switchTab('tasks'); setTimeout(() => $('#task-search')?.focus(), 0); } },
  { id: 'nav.tasks', title: 'Go to tasks', key: 'g t', run: () => switchTab('tasks') },
  { id: 'nav.queue', title: 'Go to queues', key: 'g q', run: () => switchTab('queue') },
  { id: 'nav.dashboard', title: 'Go to dashboard', key: 'g D', run: () => switchTab('dashboard') },
  { id: 'nav.settings', title: 'Go to project settings', key: 'g s', run: () => switchTab('settings') },
  { id: 'nav.wiki', title: 'Go to project wiki', key: 'g w', run: () => switchTab('wiki') },
  { id: 'nav.orgwiki', title: 'Go to organization wiki', key: 'g W', run: () => go(globalRoute('orgwiki')) },
  { id: 'nav.global', title: 'Go to organization settings', key: 'g S', run: () => switchTab('global') },
  { id: 'nav.projects', title: 'Go to projects', key: 'g P', run: () => focusRail() },
  { id: 'nav.profile', title: 'Go to your profile', key: 'g A', run: () => go(profileRoute()) },
  { id: 'nav.notifications', title: 'Go to inbox', key: 'g N', run: () => go(globalRoute('inbox')) },
  { id: 'nav.close', title: 'Close panel', key: null, run: () => closeTopOverlay() }, // Esc — handled by the dispatcher
];

function allCommands() {
  const declared = new Map((S.contributions?.commands || []).map((c) => [c.id, c]));
  const out = [];
  const add = (c) => out.push({ available: true, ...c, keys: c.keybinding ? parseKeybinding(c.keybinding) : null });
  for (const h of HOST_COMMANDS) {
    const d = declared.get(h.id);
    add({ id: h.id, title: d?.title || h.title, keybinding: d ? d.keybinding : h.key, group: 'Navigation', run: h.run });
  }
  // Interaction grammar (host-owned, not server-declared): a list cursor on the
  // tasks/queue views; with a task page open the same keys walk between tasks. When
  // focus sits in the projects rail (g p), the same keys walk the rail instead.
  const rail = inRail();
  const listy = ['tasks', 'queue'].includes(S.tab) && !rail;
  add({ id: 'list.quickAdd', title: 'Add quick task', keybinding: 'meta+Enter', group: 'List', palette: false, available: !!$('#add-task'), run: () => $('#add-task')?.click() });
  add({ id: 'list.next', title: 'Next task / row', keybinding: 'j', group: 'List', palette: false, available: listy || (!rail && !!S.selected), run: () => (S.selected ? openAdjacentTask(1) : moveCursor(1)) });
  add({ id: 'list.prev', title: 'Previous task / row', keybinding: 'k', group: 'List', palette: false, available: listy || (!rail && !!S.selected), run: () => (S.selected ? openAdjacentTask(-1) : moveCursor(-1)) });
  add({ id: 'list.next.arrow', title: 'Next task / row', keybinding: 'ArrowDown', group: 'List', palette: false, help: false, available: listy && !S.selected, run: () => moveCursor(1) });
  add({ id: 'list.prev.arrow', title: 'Previous task / row', keybinding: 'ArrowUp', group: 'List', palette: false, help: false, available: listy && !S.selected, run: () => moveCursor(-1) });
  add({ id: 'list.open', title: 'Open selected row', keybinding: 'o', group: 'List', palette: false, available: listy && !S.selected && !!S.cursorId, run: openCursorRow });
  add({ id: 'list.open.enter', title: 'Open selected row', keybinding: 'Enter', group: 'List', palette: false, help: false, available: listy && !S.selected && !!S.cursorId, run: openCursorRow });
  add({ id: 'list.archive', title: 'Archive / unarchive selected row', keybinding: 'e', group: 'List', palette: false, available: listy && !S.selected && !!S.cursorId, run: archiveCursorRow });
  // Projects rail (after g p): j/k walk projects + global entries, ↵ selects,
  // Esc returns. Same keys as the list — the two contexts are exclusive.
  add({ id: 'rail.next', title: 'Next project', keybinding: 'j', group: 'Projects', palette: false, available: rail, run: () => moveRail(1) });
  add({ id: 'rail.prev', title: 'Previous project', keybinding: 'k', group: 'Projects', palette: false, available: rail, run: () => moveRail(-1) });
  add({ id: 'rail.next.arrow', title: 'Next project', keybinding: 'ArrowDown', group: 'Projects', palette: false, help: false, available: rail, run: () => moveRail(1) });
  add({ id: 'rail.prev.arrow', title: 'Previous project', keybinding: 'ArrowUp', group: 'Projects', palette: false, help: false, available: rail, run: () => moveRail(-1) });
  add({ id: 'rail.open', title: 'Switch to project / open entry', keybinding: 'Enter', group: 'Projects', palette: false, available: rail, run: () => document.activeElement?.click() });
  add({ id: 'rail.open.o', title: 'Switch to project / open entry', keybinding: 'o', group: 'Projects', palette: false, help: false, available: rail, run: () => document.activeElement?.click() });
  // Task-page navigation (host grammar, like j/k): u goes back to the list
  // (Gmail-style — Esc does too, once overlays are popped), [ / ] cycle the
  // page's tabs. Documented in the help panel's static "On a task page" section
  // (help: false here) so they're discoverable before a page is open.
  add({ id: 'task.back', title: 'Back to the list', keybinding: 'u', group: 'Task', help: false, available: !!S.selected, run: () => closeTask() });
  add({ id: 'task.tab.prev', title: 'Previous tab', keybinding: '[', group: 'Task', help: false, available: !!(S.selected && S.view), run: () => cycleTaskTab(-1) });
  add({ id: 'task.tab.next', title: 'Next tab', keybinding: ']', group: 'Task', help: false, available: !!(S.selected && S.view), run: () => cycleTaskTab(1) });
  add({ id: 'task.checkin.prev', title: 'Previous Check-in pane', keybinding: '{', group: 'Task', help: false, available: !!(S.selected && S.view && S.taskTab === 'checkin'), run: () => cycleCheckinPane(-1) });
  add({ id: 'task.checkin.next', title: 'Next Check-in pane', keybinding: '}', group: 'Task', help: false, available: !!(S.selected && S.view && S.taskTab === 'checkin'), run: () => cycleCheckinPane(1) });
  // { / } also walk the settings rail's panes (project or organization settings).
  const onSettings = ['settings', 'organization', 'global'].includes(S.tab) && !S.selected;
  add({ id: 'settings.pane.prev', title: 'Previous settings section', keybinding: '{', group: 'Navigation', help: false, available: onSettings, run: () => cycleSettingsPane(-1) });
  add({ id: 'settings.pane.next', title: 'Next settings section', keybinding: '}', group: 'Navigation', help: false, available: onSettings, run: () => cycleSettingsPane(1) });
  // Workflow-contributed task commands: `task.<action>` binds to the selected
  // task's DECLARED action of that name — available only when the selected
  // task runs the contributing workflow and the action is currently enabled.
  const covered = new Set();
  for (const c of S.contributions?.commands || []) {
    if (c.workflow === 'core' || !c.id.startsWith('task.')) continue;
    const name = c.id.slice(5);
    covered.add(`${c.workflow}:${name}`);
    const action = S.view && S.view.workflow === c.workflow ? (S.view.actions || []).find((a) => a.name === name) : null;
    add({
      id: c.id, title: action ? taskActionLabel(S.view, action) : c.title, keybinding: c.keybinding, group: 'Task', workflow: c.workflow,
      available: !!(S.selected && action && action.enabled), danger: action?.danger,
      run: () => action && runDeclaredAction(action),
    });
  }
  // The declared-actions floor: any enabled action of the selected task not
  // already reachable through a contributed command still gets a palette entry.
  if (S.selected && S.view) {
    for (const a of S.view.actions || []) {
      if (covered.has(`${S.view.workflow}:${a.name}`)) continue;
      add({ id: `task.action.${a.name}`, title: taskActionLabel(S.view, a), group: 'Task', workflow: S.view.workflow, available: !!a.enabled, danger: a.danger, run: () => runDeclaredAction(a) });
    }
    // digits 1–9 press the Nth enabled action button in the task page's footer
    const btns = [...document.querySelectorAll('#tp-foot [data-act]:not([disabled])')].slice(0, 9);
    btns.forEach((b, i) => add({ id: `task.slot.${i + 1}`, title: `Press “${b.dataset.label || b.textContent.replace(/\d+$/, '').trim()}”`, keybinding: String(i + 1), group: 'Task', palette: false, help: false, run: () => b.click() }));
  }
  return out;
}

// Run a workflow-declared action generically: plain actions signal straight
// through the generic endpoint; the followUp action's affordance is its compose
// box; any other action with declared args gets an auto-rendered form (§10.2).
async function runDeclaredAction(a) {
  if (!S.selected) return;
  if (a.name === 'followUp') return focusFollowup();
  if (a.args && a.args.length) return openActionForm(a);
  if (!confirmTaskAction(a.name, S.view)) return;
  const taskId = S.selected;
  try {
    await api(`/api/tasks/${taskId}/signal`, { method: 'POST', body: JSON.stringify({ signal: a.name }) });
    reflectAcceptedTaskAction(taskId, a.name);
    toast(actionToast(a.name, taskActionLabel(S.view, a)));
    setTimeout(refreshTask, 250);
    setTimeout(refreshTasks, 400);
  } catch (e) { toast(e.message, true); }
}

// Auto-rendered argument form for a declared action (ActionArg[] → controls).
function openActionForm(a) {
  const root = $('#overlay-root');
  const control = (arg) => {
    const label = `<div class="label-row"><label>${esc(arg.label || arg.name)}${arg.required ? ' *' : ''}</label></div>`;
    if (arg.type === 'text') return `<div class="form-row">${label}<textarea data-arg="${esc(arg.name)}" rows="3">${esc(arg.default ?? '')}</textarea></div>`;
    if (arg.type === 'boolean') return `<div class="form-row"><div class="switch"><input type="checkbox" data-arg="${esc(arg.name)}" ${arg.default ? 'checked' : ''} /><label>${esc(arg.label || arg.name)}</label></div></div>`;
    if (arg.type === 'select') return `<div class="form-row">${label}<select data-arg="${esc(arg.name)}">${(arg.options || []).map((o) => `<option ${o === arg.default ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select></div>`;
    return `<div class="form-row">${label}<input data-arg="${esc(arg.name)}" type="${arg.type === 'number' ? 'number' : 'text'}" value="${esc(arg.default ?? '')}" /></div>`;
  };
  root.innerHTML = `<div class="palette-scrim" id="act-scrim"><div class="palette" style="width:min(480px,92vw)">
    <div style="padding:14px 16px;border-bottom:1px solid var(--line)"><b>${esc(a.label || a.name)}</b></div>
    <div style="padding:14px 16px">${(a.args || []).map(control).join('')}</div>
    <div style="padding:12px 16px;border-top:1px solid var(--line);display:flex;gap:8px;justify-content:flex-end;background:var(--surface-2)">
      <button class="btn" id="act-cancel">Cancel</button>
      <button class="btn ${a.danger ? 'danger' : 'primary'}" id="act-send">${esc(a.label || a.name)}</button>
    </div></div></div>`;
  const close = () => (root.innerHTML = '');
  $('#act-scrim').addEventListener('click', (e) => { if (e.target.id === 'act-scrim') close(); });
  $('#act-cancel').addEventListener('click', close);
  root.querySelector('[data-arg]')?.focus();
  $('#act-send').addEventListener('click', async () => {
    const body = { signal: a.name };
    for (const arg of a.args || []) {
      const el = root.querySelector(`[data-arg="${CSS.escape(arg.name)}"]`);
      if (!el) continue;
      const val = arg.type === 'boolean' ? el.checked : arg.type === 'number' ? (el.value === '' ? undefined : Number(el.value)) : el.value;
      if (arg.required && (val === undefined || val === '')) { el.focus(); return toast(`${arg.label || arg.name} is required`, true); }
      if (val !== undefined && val !== '') body[arg.name] = val;
    }
    try {
      await api(`/api/tasks/${S.selected}/signal`, { method: 'POST', body: JSON.stringify(body) });
      close();
      toast(actionToast(a.name, a.label || a.name));
      setTimeout(refreshTask, 250);
      setTimeout(refreshTasks, 400);
    } catch (e) { toast(e.message, true); }
  });
}

// Focus the selected conversation's follow-up box — the box lives per-agent on
// the Check-in tab, so switch there first if another tab is showing.
function focusFollowup() {
  if (S.taskTab !== 'checkin') setTaskTab('checkin');
  document.querySelector('.followup-input:not([disabled])')?.focus();
}

// -- list cursor (roving selection on the tasks / merge-queue views) ----------
function cursorRows() {
  return [...document.querySelectorAll('#main .task-row, #main .queue-item')];
}
function rowKey(r) { return r.dataset.id || r.dataset.draft; }
function applyCursor() {
  cursorRows().forEach((r) => r.classList.toggle('cursor', rowKey(r) === S.cursorId));
}
function moveCursor(delta) {
  const rows = cursorRows();
  if (!rows.length) return;
  let i = rows.findIndex((r) => rowKey(r) === S.cursorId);
  i = i < 0 ? (delta > 0 ? 0 : rows.length - 1) : Math.min(rows.length - 1, Math.max(0, i + delta));
  S.cursorId = rowKey(rows[i]);
  applyCursor();
  rows[i].scrollIntoView({ block: 'nearest' });
  rows[i].focus?.(); // rows carry tabindex=0, so the cursor and Tab order agree
}
function cursorRow() { return cursorRows().find((r) => rowKey(r) === S.cursorId); }
// A data-id row navigates through its .row-link `<a>` overlay (the delegated
// link router only fires for anchors), so click that; draft rows carry their
// own click handler on the div, so fall back to the row itself.
function openCursorRow() { const r = cursorRow(); if (r) (r.querySelector('a.row-link') || r).click(); }
function archiveCursorRow() { cursorRow()?.querySelector('[data-archive],[data-unarchive]')?.click(); }
// With a task page open, j/k walk the same task order the list shows.
function taskOrder() {
  return S.tasks
    .filter((t) => !t.params?.draft && (!S.search || t.title.toLowerCase().includes(S.search.toLowerCase())))
    .slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
    .map((t) => t.id);
}
function openAdjacentTask(delta) {
  const order = taskOrder();
  const i = order.indexOf(S.selected);
  const next = order[i < 0 ? 0 : i + delta];
  if (next) { S.cursorId = next; goToTask(next); }
}

// -- projects rail focus (g p): walk projects + global entries by keyboard ----
function railRows() { return [...document.querySelectorAll('#rail .rail-add, #rail .project-link, #rail .folder-toggle, #rail .nav-item')]; }
function inRail() { return !!(document.activeElement && document.activeElement.closest && document.activeElement.closest('#rail')); }
function focusRail() {
  const rows = railRows();
  (rows.find((r) => r.dataset.id === S.projectId) || rows[0])?.focus();
}
function moveRail(delta) {
  const rows = railRows();
  if (!rows.length) return;
  let i = rows.indexOf(document.activeElement);
  i = i < 0 ? 0 : Math.min(rows.length - 1, Math.max(0, i + delta));
  rows[i].focus();
  rows[i].scrollIntoView({ block: 'nearest' });
}

// -- Escape layering: pop the topmost surface ---------------------------------
function closeTopOverlay() {
  // Secondary modals (task picker, filter picker, tags manager, tag picker) stack
  // above the form/page in #modal-root — pop the topmost one first (a filter
  // picker can itself sit on the task-picker overlay).
  if ($('#modal-root').lastElementChild) return $('#modal-root').lastElementChild.remove();
  const overlay = $('#overlay-root').firstElementChild;
  if (overlay) {
    if (overlay.id === 'tf-page') return overlay.querySelector('#tf-close')?.click(); // task form page: its close flushes the draft
    return ($('#overlay-root').innerHTML = '');
  }
  if (S.selected) return closeTask();
}

// -- the dispatcher ------------------------------------------------------------
const CHORD = { pending: [], timer: 0 };
function resetChord() { CHORD.pending = []; clearTimeout(CHORD.timer); }
// A bare modifier keydown (Shift/Ctrl/Alt/Meta) fires on its own before the key
// it modifies. It must be transparent to the chord buffer — otherwise pressing
// Shift for the second step of a shifted chord (`g P`, `g W`, `g D`, `g S`, …)
// would land here between the two steps, match nothing, and reset the pending
// `g` before `P` ever arrives.
function isBareModifier(key) { return key === 'Shift' || key === 'Control' || key === 'Alt' || key === 'Meta'; }
// Plain Enter belongs to the control that actually has focus. Native
// controls already activate themselves; custom controls use tabindex/role and
// need a synthetic click. Command-modified Enter is deliberately excluded so
// page-level shortcuts such as Ctrl/Cmd+Enter remain global.
function focusedEnterAction(e, target) {
  if (e.key !== 'Enter' || e.metaKey || e.ctrlKey || e.altKey || !target?.closest) return null;
  if (target.closest('button, a[href], summary')) return 'native';
  if (target.closest('[role="button"], [tabindex="0"]')) return 'click';
  return null;
}
function dispatchKey(e) {
  if (isBareModifier(e.key)) return false;
  const snap = { key: e.key, metaKey: e.metaKey, ctrlKey: e.ctrlKey, altKey: e.altKey, shiftKey: e.shiftKey };
  const cmds = allCommands().filter((c) => c.keys && c.available);
  const candidates = chordCandidates(cmds, CHORD.pending, snap);
  if (!candidates.length) { resetChord(); return false; }
  e.preventDefault();
  const exact = candidates.find((c) => c.keys.length === CHORD.pending.length + 1);
  const longer = candidates.some((c) => c.keys.length > CHORD.pending.length + 1);
  if (exact && !longer) { resetChord(); exact.run(); return true; }
  CHORD.pending.push(snap); // a chord prefix ('g' …) — wait briefly for the rest
  clearTimeout(CHORD.timer);
  CHORD.timer = setTimeout(resetChord, 900);
  return true;
}
function bindKeys() {
  document.addEventListener('keydown', (e) => {
    const t = e.target;
    // A component-level handler that prevented the event already owns it (for
    // example a composite role=button with richer Enter/Space behavior).
    if (e.defaultPrevented) return;
    // The check-in terminal is a focusable <pre> that behaves like a text field:
    // keystrokes go to the shell, not to app shortcuts. Treat it as "typing".
    const typing = t && t.matches && (t.matches('input, textarea, select, .term-screen') || t.isContentEditable);
    const overlayOpen = $('#overlay-root').childElementCount > 0 || $('#modal-root').childElementCount > 0;
    if (typing) {
      if (e.key === 'Escape') { t.blur(); resetChord(); }
      // modifier-bearing bindings (⌘K) still work while typing outside overlays
      else if ((e.metaKey || e.ctrlKey) && !overlayOpen) dispatchKey(e);
      return;
    }
    // Focus wins over global commands for plain Enter, including inside an
    // overlay. Native controls need no help; custom tabindex/role controls do.
    const focusedAction = focusedEnterAction(e, t);
    if (focusedAction === 'native') return;
    if (focusedAction === 'click') {
      e.preventDefault();
      t.closest('[role="button"], [tabindex="0"]').click();
      return;
    }
    if (overlayOpen) { // an overlay owns the keyboard; Esc pops it
      if (e.key === 'Escape') closeTopOverlay();
      return;
    }
    if (e.key === 'Escape') {
      resetChord();
      if (inRail()) return document.activeElement.blur(); // leave the rail, don't close panels
      return closeTopOverlay();
    }
    if (dispatchKey(e)) return;
  });
}

// -- global search: read-only discovery across every accessible project -------
// Keep this separate from the command palette: search finds durable things;
// the palette invokes actions. The per-project search endpoint gives this the
// same free-text + field-filter semantics as the task list without loading every
// project's task collection into browser state.
function assembleGlobalSearchResults(query, projects, responses, limit = 40) {
  const q = String(query || '').trim();
  const hasFilterSyntax = /(?:^|\s)[!-]?[\w.-]+:/.test(q);
  const textTerms = (q.match(/"[^"]+"|\S+/g) || [])
    .filter((term) => !/^[!-]?[\w.-]+:/.test(term))
    .map((term) => term.replace(/^"|"$/g, ''));
  const projectHits = hasFilterSyntax ? [] : (projects || [])
    .map((project) => ({ project, score: fuzzyScore(q, project.name) }))
    .filter((hit) => hit.score >= 0)
    .sort((a, b) => b.score - a.score || a.project.name.localeCompare(b.project.name))
    .slice(0, 8);

  const allTasks = (responses || []).flatMap(({ project, result }) =>
    (result?.tasks || []).map((task) => ({
      task,
      project,
      // Text hits in the title should lead notes-only matches. Structured
      // queries have no text terms, so their cross-project order falls back to
      // recency. Score terms independently because task free text is intentionally
      // order-independent ("login fix" also matches "Fix login redirect").
      score: textTerms.length
        ? textTerms.reduce((total, term) => {
          const termScore = fuzzyScore(term, task.title);
          return total < 0 || termScore < 0 ? -1 : total + termScore;
        }, 0)
        : 0,
    })),
  );
  allTasks.sort((a, b) => b.score - a.score || (b.task.createdAt || 0) - (a.task.createdAt || 0));
  return { projectHits, taskHits: allTasks.slice(0, limit), totalTasks: allTasks.length };
}

function openGlobalSearch() {
  const root = $('#overlay-root');
  root.innerHTML = `<div class="palette-scrim" id="gs-scrim"><div class="palette global-search" role="dialog" aria-modal="true" aria-labelledby="gs-title">
    <div class="global-search-head">
      <span aria-hidden="true">⌕</span>
      <input id="gs-in" aria-label="Search everything" aria-controls="gs-list" aria-autocomplete="list" placeholder="Search tasks and projects…" autocomplete="off" spellcheck="false" />
      <button class="icon-btn" id="gs-close" title="Close" aria-label="Close search">✕</button>
    </div>
    <div class="global-search-context" id="gs-title">Every accessible project · title, notes, task number, status, tags, and more</div>
    <div id="gs-list" role="listbox" aria-label="Search results" aria-live="polite"></div>
    <div class="global-search-foot">Filter tasks with queries like <code>status:active</code>, <code>tag:frontend</code>, or <code>#42</code>.</div>
  </div></div>`;
  const input = $('#gs-in');
  const list = $('#gs-list');
  let items = [];
  let active = 0;
  let timer = 0;
  let request = 0;
  let state = 'prompt';
  let summary = '';
  const close = () => { clearTimeout(timer); request++; root.innerHTML = ''; };

  const draw = () => {
    if (state === 'prompt') {
      input.removeAttribute('aria-activedescendant');
      list.innerHTML = `<div class="global-search-empty"><b>Find work anywhere</b><span>Enter words, a task number, or a task filter. Results include archived work.</span></div>`;
      return;
    }
    if (state === 'loading') {
      input.removeAttribute('aria-activedescendant');
      list.innerHTML = `<div class="global-search-empty"><span class="global-search-loading">Searching ${S.projects.length} project${S.projects.length === 1 ? '' : 's'}…</span></div>`;
      return;
    }
    if (!items.length) {
      input.removeAttribute('aria-activedescendant');
      list.innerHTML = `<div class="global-search-empty"><b>No results</b><span>No accessible task or project matched this search.</span></div>`;
      return;
    }
    let lastGroup = null;
    list.innerHTML = items.map((item, i) => {
      const head = item.group !== lastGroup ? `<div class="pal-group">${esc(item.group)}</div>` : '';
      lastGroup = item.group;
      // Each result is a real permalink, so it opens in a new tab with any native
      // gesture (Ctrl/⌘-click, middle-click, right-click → Open in new tab); a plain
      // click below still opens it in place and dismisses the palette.
      return `${head}<a class="opt global-search-result ${i === active ? 'active' : ''}" id="gs-result-${i}" role="option" aria-selected="${i === active}" data-i="${i}"${item.href ? ` data-spa href="${esc(item.href)}"` : ''}>
        <span class="global-search-kind" aria-hidden="true">${item.group === 'Projects' ? ICON.project : '□'}</span>
        <span class="global-search-copy"><b>${esc(item.title)}</b><span>${esc(item.sub || '')}</span></span>
      </a>`;
    }).join('');
    input.setAttribute('aria-activedescendant', `gs-result-${active}`);
    if (summary) list.insertAdjacentHTML('beforeend', `<div class="global-search-summary">${esc(summary)}</div>`);
    list.querySelector('.opt.active')?.scrollIntoView({ block: 'nearest' });
  };

  const search = async () => {
    const q = input.value.trim();
    const ownRequest = ++request;
    if (!q) { state = 'prompt'; items = []; summary = ''; active = 0; return draw(); }
    state = 'loading';
    draw();
    const responses = (await Promise.all(S.projects.map(async (project) => {
      try {
        const result = await api(`/api/projects/${encodeURIComponent(project.id)}/search?q=${encodeURIComponent(q)}`);
        return { project, result };
      } catch { return null; } // project discovery and task-read grants can differ
    }))).filter(Boolean);
    if (ownRequest !== request || !root.contains(input)) return;
    const found = assembleGlobalSearchResults(q, S.projects, responses);
    items = [
      ...found.projectHits.map(({ project }) => {
        const href = projectRoute(project.id);
        return { group: 'Projects', title: project.name, sub: 'Open project', href, run: () => spaNavigate(href) };
      }),
      ...found.taskHits.map(({ project, task }) => {
        const stateLabel = task.params?.draft ? 'draft' : task.params?.archived ? 'archived' : task.lastView?.stage || task.lastView?.status || task.workflow;
        const number = task.num != null ? `#${task.num} · ` : '';
        const href = `${projectBase(project.id)}/tasks/${task.num != null ? task.num : encodeURIComponent(task.id)}`;
        return {
          group: 'Tasks', title: task.title,
          sub: `${number}${project.name} · ${stateLabel}`,
          href, run: () => spaNavigate(href),
        };
      }),
    ];
    summary = found.totalTasks > found.taskHits.length ? `Showing ${found.taskHits.length} of ${found.totalTasks} matching tasks` : '';
    active = 0;
    state = 'done';
    draw();
  };
  const schedule = () => { request++; clearTimeout(timer); timer = setTimeout(search, 160); };
  const run = (i) => { const item = items[i]; if (!item) return; close(); item.run(); };

  input.addEventListener('input', schedule);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.stopPropagation(); close(); }
    else if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(items.length - 1, active + 1); draw(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(0, active - 1); draw(); }
    else if (e.key === 'Enter') { e.preventDefault(); run(active); }
  });
  list.addEventListener('click', (e) => {
    const row = e.target.closest('.opt'); if (!row) return;
    if (isNewTabClick(e)) return; // real <a> result → let the browser open it in a new tab (palette stays open)
    e.preventDefault();
    run(Number(row.dataset.i));
  });
  list.addEventListener('mousemove', (e) => { const row = e.target.closest('.opt'); if (row && Number(row.dataset.i) !== active) { active = Number(row.dataset.i); draw(); } });
  $('#gs-close').addEventListener('click', close);
  $('#gs-scrim').addEventListener('click', (e) => { if (e.target.id === 'gs-scrim') close(); });
  draw();
  input.focus();
}

// -- the ⌘K palette: fuzzy command/action invocation --------------------------
function openPalette() {
  const root = $('#overlay-root');
  root.innerHTML = `<div class="palette-scrim" id="pal-scrim"><div class="palette">
    <input id="pal-in" placeholder="Type a command…" autocomplete="off" />
    <div id="pal-list"></div>
  </div></div>`;
  const input = $('#pal-in');
  const list = $('#pal-list');
  const close = () => (root.innerHTML = '');
  let items = [];
  let active = 0;
  const GROUP_ORDER = { Task: 0, Navigation: 1, List: 2 };
  const build = () => {
    const q = input.value.trim();
    items = [];
    for (const c of allCommands()) {
      if (c.palette === false || !c.available) continue;
      const score = fuzzyScore(q, c.title);
      if (score < 0) continue;
      items.push({ group: c.group, title: c.title, kbd: c.keybinding, sub: c.workflow, danger: c.danger, score, run: c.run });
    }
    items.sort((a, b) => (GROUP_ORDER[a.group] ?? 9) - (GROUP_ORDER[b.group] ?? 9) || b.score - a.score);
    items = items.slice(0, 14);
    active = 0;
    draw();
  };
  const draw = () => {
    let lastGroup = null;
    list.innerHTML = items.map((it, i) => {
      const head = it.group !== lastGroup ? `<div class="pal-group">${esc(it.group)}</div>` : '';
      lastGroup = it.group;
      return `${head}<div class="opt ${i === active ? 'active' : ''}${it.danger ? ' danger' : ''}" data-i="${i}">${esc(it.title)}${it.sub ? `<span class="pal-sub">${esc(it.sub)}</span>` : ''}${it.kbd ? `<span class="key">${esc(fmtKeys(it.kbd))}</span>` : ''}</div>`;
    }).join('') || `<div class="pal-empty">No matches</div>`;
    list.querySelector('.opt.active')?.scrollIntoView({ block: 'nearest' });
  };
  const run = (i) => { const it = items[i]; if (!it) return; close(); it.run(); };
  input.addEventListener('input', build);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.stopPropagation(); close(); }
    else if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(items.length - 1, active + 1); draw(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(0, active - 1); draw(); }
    else if (e.key === 'Enter') { e.preventDefault(); run(active); }
  });
  list.addEventListener('click', (e) => { const o = e.target.closest('.opt'); if (o) run(Number(o.dataset.i)); });
  list.addEventListener('mousemove', (e) => { const o = e.target.closest('.opt'); if (o && Number(o.dataset.i) !== active) { active = Number(o.dataset.i); draw(); } });
  $('#pal-scrim').addEventListener('click', (e) => { if (e.target.id === 'pal-scrim') close(); });
  build();
  input.focus();
}

// -- "?" help: the same registry, grouped — includes every workflow's commands -
function openHelp() {
  const root = $('#overlay-root');
  const cmds = allCommands().filter((c) => c.keybinding && c.help !== false);
  const groups = [...new Set(cmds.map((c) => c.group))];
  const row = (k, title, sub) => `<div class="help-row"><span class="key">${k}</span><span>${title}${sub ? ` <span class="pal-sub">${esc(sub)}</span>` : ''}</span></div>`;
  root.innerHTML = `<div class="palette-scrim" id="help-scrim"><div class="palette" style="width:min(560px,92vw);max-height:80vh;overflow:auto">
    <div style="padding:14px 16px;border-bottom:1px solid var(--line);display:flex;align-items:center"><b>Keyboard shortcuts</b><span style="flex:1"></span><button class="icon-btn" id="help-close">✕</button></div>
    <div style="padding:6px 16px 16px">
      ${groups.map((g) => `<div class="section-h">${esc(g)}</div>${cmds.filter((c) => c.group === g).map((c) => row(esc(fmtKeys(c.keybinding)), esc(c.title), c.workflow)).join('')}`).join('')}
      <div class="section-h">On a task page</div>
      ${row('1–9', 'Press the Nth action button (whatever the workflow declares)')}
      ${row('[ / ]', 'Previous / next tab')}
      ${row('{ / }', 'Previous / next Check-in pane')}
      ${row('u', 'Back to the list')}
      ${row(esc(fmtKeys('meta+Enter')), 'Send follow-up (from inside the compose box)')}
      ${row('Esc', 'Close the topmost panel / leave a text field')}
      <div class="section-h">Quick add</div>
      ${row('↵', 'Open the full task form with what you typed')}
      ${row(esc(fmtKeys('meta+Enter')), 'Add the task directly')}
    </div></div></div>`;
  $('#help-close').addEventListener('click', () => (root.innerHTML = ''));
  $('#help-scrim').addEventListener('click', (e) => { if (e.target.id === 'help-scrim') root.innerHTML = ''; });
}

// ── login ────────────────────────────────────────────────────────────────────

// "Continue with Google" — Better Auth's own social endpoint (the gateway proxies
// /api/auth/* verbatim, so there is no karmax route here). Sign-in and sign-up are
// the same call: Google either matches an existing account or creates one.
// The provider-specific treatment follows Google's button guidance so this trust
// boundary is recognizable before someone clicks it. Keep the G paths inline: the
// sign-in card must work without a third-party asset request.
const googleBtn = (id) => S.google
  ? `<button class="google-signin-btn" id="${id}" type="button">
      <svg class="google-signin-mark" viewBox="0 0 18 18" aria-hidden="true">
        <path fill="#4285F4" d="M17.64 9.205c0-.638-.057-1.252-.164-1.841H9v3.481h4.844a4.14 4.14 0 0 1-1.797 2.716v2.258h2.909c1.702-1.567 2.684-3.875 2.684-6.614Z" />
        <path fill="#34A853" d="M9 18c2.43 0 4.468-.806 5.956-2.181l-2.909-2.258c-.806.54-1.835.859-3.047.859-2.344 0-4.328-1.585-5.037-3.714H.956v2.333A9 9 0 0 0 9 18Z" />
        <path fill="#FBBC05" d="M3.963 10.706A5.42 5.42 0 0 1 3.682 9c0-.592.102-1.167.281-1.706V4.961H.956A9 9 0 0 0 0 9c0 1.452.347 2.827.956 4.039l3.007-2.333Z" />
        <path fill="#EA4335" d="M9 3.58c1.321 0 2.507.454 3.441 1.346l2.582-2.582C13.464.892 11.43 0 9 0A9 9 0 0 0 .956 4.961l3.007 2.333C4.672 5.165 6.656 3.58 9 3.58Z" />
      </svg>
      <span>Continue with Google</span>
      <span aria-hidden="true"></span>
    </button>`
  : '';

// GitHub's mark and high-contrast neutral treatment make the second identity
// option immediately legible without borrowing Google's visual language. The
// path is inline so authentication never depends on a third-party asset host.
const githubBtn = (id) => S.github
  ? `<button class="github-signin-btn" id="${id}" type="button">
      <svg class="github-signin-mark" viewBox="0 0 24 24" aria-hidden="true">
        <path fill="currentColor" d="M12 .7a11.5 11.5 0 0 0-3.64 22.41c.58.11.79-.25.79-.56v-2.24c-3.23.7-3.91-1.37-3.91-1.37-.53-1.34-1.29-1.7-1.29-1.7-1.05-.72.08-.71.08-.71 1.17.08 1.78 1.2 1.78 1.2 1.04 1.77 2.72 1.26 3.38.96.1-.75.4-1.26.74-1.55-2.58-.29-5.29-1.29-5.29-5.69 0-1.26.45-2.28 1.19-3.09-.12-.29-.52-1.47.11-3.05 0 0 .97-.31 3.16 1.18A10.9 10.9 0 0 1 12 6.1c.98 0 1.95.13 2.87.39 2.19-1.49 3.16-1.18 3.16-1.18.63 1.58.23 2.76.11 3.05.74.81 1.19 1.83 1.19 3.09 0 4.42-2.72 5.39-5.3 5.68.42.36.79 1.07.79 2.16v3.26c0 .31.21.68.8.56A11.5 11.5 0 0 0 12 .7Z" />
      </svg>
      <span>Continue with GitHub</span>
      <span aria-hidden="true"></span>
    </button>`
  : '';

// What a failed social-provider round trip means, in the user's terms. Better Auth
// would otherwise land them on its own `/api/auth/error` page — a bare error
// code and an "Ask AI" button, off karmax entirely, with no way back.
//
// `account_not_linked` is the one that is neither a bug nor a dead end, and it
// has a real cause: karmax's email+password signup does not verify addresses, so
// Better Auth refuses to merge a social identity into a local account that only
// *claims* that address (otherwise registering someone else's address here would
// capture their provider sign-in). The password still works — say so.
const SOCIAL_SIGN_IN_ERRORS = {
  account_not_linked: 'An account already exists for that email address with a password. '
    + 'Sign in with that password instead — social sign-in requires confirming the address first.',
};

function socialSignInError(params) {
  const code = params.get('error');
  if (!code) return undefined;
  const provider = params.get('auth_provider') === 'github' ? 'GitHub' : 'Google';
  return SOCIAL_SIGN_IN_ERRORS[code] ?? `${provider} sign-in failed (${code}).`;
}

function wireSocialBtn(id, provider, errSelector, requireAcceptance = false) {
  $(`#${id}`)?.addEventListener('click', async () => {
    try {
      if (requireAcceptance) {
        const acceptance = readPolicyAcceptance('signup');
        const accepted = await feedbackFetch('/api/legal/preaccept', { method: 'POST', headers: { 'content-type': 'application/json' },
          body: JSON.stringify(acceptance) });
        if (!accepted.ok) throw new Error((await accepted.json().catch(() => ({}))).error || 'Accept the current policies to create an account.');
      }
      // errorCallbackURL keeps a rejected sign-in on karmax's own card: Better
      // Auth appends `?error=<code>`, which boot() reads back on the way in.
      const back = new URL(location.href);
      back.searchParams.delete('error');
      back.searchParams.delete('auth_provider');
      const errorBack = new URL(back);
      errorBack.searchParams.set('auth_provider', provider);
      const response = await feedbackFetch('/api/auth/sign-in/social', { method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ provider, callbackURL: back.href, errorCallbackURL: errorBack.href }) });
      const result = await response.json();
      const label = provider === 'github' ? 'GitHub' : 'Google';
      if (!response.ok || !result.url) throw new Error(result.error || result.message || `${label} sign-in unavailable`);
      location.href = result.url;
    } catch (error) { $(errSelector).textContent = error.message; }
  });
}

// ── public landing ──────────────────────────────────────────────────────────

function policyLinks(slugs) {
  const bySlug = new Map((S.launch?.policies || []).map((policy) => [policy.slug, policy]));
  return slugs.map((slug) => {
    const policy = bySlug.get(slug);
    return `<a href="/legal/${slug}" target="_blank" rel="noopener">${esc(policy?.title || slug)} <span class="mono">v${esc(policy?.version || S.launch?.policyVersion || '')}</span></a>`;
  }).join(', ');
}

function policyAcceptanceMarkup(context, id) {
  const slugs = Object.keys(S.launch?.acceptance?.[context] || {});
  return `<label class="policy-acceptance" for="${id}"><input type="checkbox" id="${id}" />
    <span>I agree to the current ${policyLinks(slugs)}.</span></label>`;
}

function readPolicyAcceptance(context) {
  const box = $(`#${context}-policy-acceptance`);
  if (!box?.checked) throw new Error('Accept the current policies to continue.');
  return { accepted: true, versions: S.launch?.acceptance?.[context] || {} };
}

function legalFooter() {
  return `<footer class="legal-footer"><a href="/">krmax</a><a href="/pricing">Pricing</a><a href="/legal">Policies</a>
    <a href="/legal/security">Security</a><a href="/legal/dpa">DPA requests</a></footer>`;
}

async function renderLegalPage(slug) {
  document.body.classList.remove('landing-active');
  const response = await feedbackFetch(`/api/legal/${encodeURIComponent(slug)}`);
  if (!response.ok) { history.replaceState({}, '', '/legal'); return renderLegalIndex(); }
  const policy = await response.json();
  document.title = `${policy.title} · krmax`;
  const contactRows = Object.entries(policy.contacts || {}).filter(([, email]) => email)
    .map(([kind, email]) => `<a href="mailto:${esc(email)}">${esc(kind)}: ${esc(email)}</a>`).join('');
  $('#app').innerHTML = `<div class="legal-shell"><header class="legal-nav"><a href="/" class="landing-brand">${brandMark()}<span>krmax</span></a><a href="/legal">All policies</a></header>
    <main class="legal-document"><div class="legal-kicker">Version ${esc(policy.version)} · Effective ${esc(policy.effectiveDate)}</div>
    <h1>${esc(policy.title)}</h1><p class="legal-summary">${esc(policy.summary)}</p>
    <div class="legal-draft" role="note"><b>Launch draft</b><span>${esc(policy.draftNotice)}</span></div>
    ${policy.operator ? `<p class="legal-operator"><b>Configured operator:</b> ${esc(policy.operator.name)}${policy.operator.country ? ` · ${esc(policy.operator.country)}` : ''}${policy.operator.governingLaw ? `<br><b>Governing law:</b> ${esc(policy.operator.governingLaw)}` : ''}${policy.operator.legalNoticeAddress ? `<br><b>Legal notices:</b> ${esc(policy.operator.legalNoticeAddress)}` : ''}</p>`
      : '<p class="legal-unresolved"><b>Launch configuration incomplete:</b> the contracting entity and jurisdiction fields are intentionally not represented.</p>'}
    ${policy.sections.map((section) => `<section><h2>${esc(section.heading)}</h2>${section.paragraphs.map((text) => `<p>${esc(text)}</p>`).join('')}
      ${section.bullets?.length ? `<ul>${section.bullets.map((text) => `<li>${esc(text)}</li>`).join('')}</ul>` : ''}</section>`).join('')}
    ${contactRows ? `<div class="legal-contacts">${contactRows}</div>` : ''}</main>${legalFooter()}</div>`;
  window.onpopstate = () => boot();
}

function renderLegalIndex() {
  document.body.classList.remove('landing-active');
  document.title = 'Policies · krmax';
  $('#app').innerHTML = `<div class="legal-shell"><header class="legal-nav"><a href="/" class="landing-brand">${brandMark()}<span>krmax</span></a><a href="/pricing">Pricing</a></header>
    <main class="legal-index"><div class="legal-kicker">Launch policy set · v${esc(S.launch?.policyVersion)}</div><h1>Policies &amp; trust</h1>
    <p class="legal-summary">Versioned product, billing, privacy, and operational disclosures for the initial paid launch.</p>
    <div class="legal-draft" role="note"><b>Launch draft</b><span>${esc(S.launch?.draftNotice)}</span></div>
    <div class="legal-grid">${(S.launch?.policies || []).map((policy) => `<a href="/legal/${policy.slug}"><span>${esc(policy.title)}</span><small>${esc(policy.summary)}</small><i>v${esc(policy.version)} →</i></a>`).join('')}</div>
    </main>${legalFooter()}</div>`;
  window.onpopstate = () => boot();
}

function formatCatalogPrice(cents, currency = 'usd') {
  return new Intl.NumberFormat(undefined, { style: 'currency', currency: currency.toUpperCase(),
    minimumFractionDigits: 0, maximumFractionDigits: 2 }).format(Number(cents || 0) / 100);
}

function renderPricing() {
  document.body.classList.remove('landing-active');
  document.title = 'Pricing · krmax';
  const catalog = S.launch?.pricingCatalog || [];
  const checkoutReady = S.launch?.paidLaunch && S.launch?.ready;
  const team = catalog.find((plan) => plan.id === 'team');
  const cards = catalog.map((plan) => {
    const price = formatCatalogPrice(plan.monthlyBasePriceCents, plan.currency);
    const users = plan.id === 'team'
      ? `First active user included, then ${formatCatalogPrice(plan.monthlyAdditionalActiveUserPriceCents, plan.currency)} per additional active user per month`
      : `${plan.maxMembers} user`;
    const priceLine = plan.id === 'free' ? price : `${price}<small> / month</small>`;
    return `<article class="price-card" data-plan="${esc(plan.id)}"><div class="price-name">${esc(plan.name)}</div>
      <div class="price-value">${priceLine}</div><p>${esc(users)}</p><ul><li>Unlimited projects</li>
      <li>${esc(plan.maxActiveAgentRuns)} concurrent agent run${plan.maxActiveAgentRuns === 1 ? '' : 's'}${plan.id === 'team' ? ` shared across the organization + ${esc(plan.additionalActiveUserAgentRuns)} per additional active user` : ''}</li></ul>
      ${plan.id === 'free' || checkoutReady ? '<a class="btn primary" href="/signup">Create account</a>' : '<span class="price-unavailable">Paid checkout is not yet enabled.</span>'}</article>`;
  }).join('');
  $('#app').innerHTML = `<div class="legal-shell"><header class="legal-nav"><a href="/" class="landing-brand">${brandMark()}<span>krmax</span></a><a href="/login">Sign in</a></header>
    <main class="pricing-page"><div class="legal-kicker">Hosted plans</div><h1>Free, Individual, and Team</h1>
      <p class="legal-summary">All plans include unlimited projects. Concurrency is a maximum number of active agent runs, not reserved capacity.</p>
      <div class="pricing-grid">${cards}</div>
      <div class="pricing-terms"><p>Individual and Team renew monthly until canceled. Team is ${esc(formatCatalogPrice(team?.monthlyBasePriceCents, team?.currency))} per month including the first active user, plus ${esc(formatCatalogPrice(team?.monthlyAdditionalActiveUserPriceCents, team?.currency))} per additional active user per month. Cancel online from Organization settings; cancellation normally stops the next renewal and access continues through the paid period. Payments are non-refundable except where law requires or checkout expressly states otherwise.</p>
      ${!checkoutReady ? '<p class="legal-unresolved"><b>Paid checkout disabled:</b> the operator must complete the founder-reviewed entity, jurisdiction, and contact launch configuration before accepting charges.</p>' : ''}
      <p class="price-policy">${policyLinks(['terms', 'privacy', 'billing'])}</p></div></main>${legalFooter()}</div>`;
  window.onpopstate = () => boot();
}

function openPublicAuth(path, render) {
  history.pushState({ kx: 1 }, '', path);
  render();
}

