function renderLogin() {
  document.body.classList.remove('landing-active');
  document.title = 'Sign in · krmax';
  window.onpopstate = () => boot();
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <a href="/" id="login-home" class="login-home">← About krmax</a>
    <div class="brand" style="margin-bottom:18px">${brandMark()} krmax</div>
    ${S.justVerified ? '<p class="task-sub" style="color:var(--merged)">✓ Email confirmed. Sign in to continue.</p>' : ''}
    ${S.pendingInvite ? '<p class="task-sub">You\'ve been invited to a krmax organization. Sign in — or <b>create an account</b> — to accept it.</p>' : ''}
    <div class="form-row"><label>Email</label><input type="email" id="email" autocomplete="username" /></div>
    <div class="form-row"><label>Password</label><input type="password" id="pw" /></div>
    <button class="btn primary" id="login-btn" style="width:100%">Sign in</button>
    ${googleBtn('google-btn')}
    ${githubBtn('github-btn')}
    ${S.sso ? '<button class="btn" id="sso-btn" style="width:100%;margin-top:8px">Continue with company SSO</button>' : ''}
    <button class="btn" id="signup-open" style="width:100%;margin-top:8px">Create account</button>
    <div style="text-align:center;margin-top:10px"><a href="#" id="forgot-open" style="color:var(--ink-3);font-size:12px">Forgot password?</a></div>
    <div id="login-err" style="color:var(--danger);font-size:12px;margin-top:8px">${S.signInError ? esc(S.signInError) : ''}</div>
  </div></div>`;
  const go = async () => {
    const email = $('#email').value.trim();
    const password = $('#pw').value;
    if (!email || !password) {
      $('#login-err').textContent = 'Enter your email and password.';
      (!email ? $('#email') : $('#pw')).focus();
      return;
    }
    $('#login-err').textContent = '';
    try {
      const res = await feedbackFetch('/api/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, password }) });
      if (res.ok) boot(); else $('#login-err').textContent = 'Invalid email or password';
    } catch { $('#login-err').textContent = 'Login failed'; }
  };
  $('#login-btn').addEventListener('click', go);
  $('#login-home')?.addEventListener('click', (e) => { e.preventDefault(); history.pushState({ kx: 1 }, '', '/'); renderLanding(); });
  wireSocialBtn('google-btn', 'google', '#login-err');
  wireSocialBtn('github-btn', 'github', '#login-err');
  $('#sso-btn')?.addEventListener('click', async () => {
    try {
      const response = await feedbackFetch('/api/sso/start', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ callbackURL: location.href }) });
      const result = await response.json();
      if (!response.ok || !result.url) throw new Error(result.error || 'SSO unavailable');
      location.href = result.url;
    } catch (error) { $('#login-err').textContent = error.message; }
  });
  $('#signup-open').addEventListener('click', () => openPublicAuth('/signup', renderSignup));
  $('#forgot-open').addEventListener('click', (e) => { e.preventDefault(); renderForgotPassword(); });
  $('#pw').addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
}

// Request a password-reset email. Better Auth mails a link back to /reset-password
// (renderResetPassword); the response is intentionally uniform so we never reveal
// whether an address has an account.
function renderForgotPassword() {
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <div class="brand" style="margin-bottom:12px">${brandMark()} Reset password</div>
    <p class="task-sub">Enter your email and we'll send you a link to choose a new password.</p>
    <div class="form-row"><label>Email</label><input type="email" id="forgot-email" autocomplete="username" /></div>
    <button class="btn primary" id="forgot-btn" style="width:100%">Send reset link</button>
    <button class="btn" id="forgot-back" style="width:100%;margin-top:8px">Back to sign in</button>
    <div id="forgot-msg" style="font-size:12px;margin-top:8px"></div>
  </div></div>`;
  const go = async () => {
    const email = $('#forgot-email').value.trim();
    if (!email || !$('#forgot-email').checkValidity()) {
      $('#forgot-msg').style.color = 'var(--danger)';
      $('#forgot-msg').textContent = 'Enter a valid email address.';
      $('#forgot-email').focus();
      return;
    }
    $('#forgot-btn').disabled = true;
    try {
      await feedbackFetch('/api/auth/request-password-reset', { method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ email, redirectTo: `${location.origin}/reset-password` }) });
    } catch {}
    $('#forgot-msg').style.color = 'var(--ink-2)';
    $('#forgot-msg').textContent = 'If an account exists for that address, a reset link is on its way. Check your email.';
    $('#forgot-btn').disabled = false;
  };
  $('#forgot-btn').addEventListener('click', go);
  $('#forgot-back').addEventListener('click', renderLogin);
  $('#forgot-email').addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
}

// Landing page for the emailed reset link (/reset-password?token=…). Sets a new
// password via Better Auth, then returns to sign in.
function renderResetPassword(token) {
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <div class="brand" style="margin-bottom:12px">${brandMark()} Choose a new password</div>
    ${token ? `<div class="form-row"><label>New password (10+ characters)</label><input type="password" id="reset-pw" autocomplete="new-password" /></div>
    <button class="btn primary" id="reset-btn" style="width:100%">Set new password</button>`
      : `<p class="task-sub">This reset link is missing its token or has expired. Request a new one from the sign-in page.</p>`}
    <button class="btn" id="reset-back" style="width:100%;margin-top:8px">Back to sign in</button>
    <div id="reset-msg" style="font-size:12px;margin-top:8px"></div>
  </div></div>`;
  const go = async () => {
    const newPassword = $('#reset-pw').value;
    if (!newPassword || newPassword.length < 10) { $('#reset-msg').style.color = 'var(--danger)'; $('#reset-msg').textContent = 'Password must be at least 10 characters.'; return; }
    $('#reset-btn').disabled = true;
    try {
      const res = await feedbackFetch('/api/auth/reset-password', { method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ newPassword, token }) });
      if (res.ok) {
        $('#reset-msg').style.color = 'var(--ink-2)';
        $('#reset-msg').textContent = 'Password updated. Redirecting to sign in…';
        setTimeout(() => { history.replaceState({ kx: 1 }, '', '/'); renderLogin(); }, 1200);
      } else {
        const err = await res.json().catch(() => ({}));
        $('#reset-msg').style.color = 'var(--danger)';
        $('#reset-msg').textContent = err.message || err.error || 'Could not reset password. The link may have expired.';
        $('#reset-btn').disabled = false;
      }
    } catch { $('#reset-msg').style.color = 'var(--danger)'; $('#reset-msg').textContent = 'Could not reset password.'; $('#reset-btn').disabled = false; }
  };
  $('#reset-btn')?.addEventListener('click', go);
  $('#reset-back').addEventListener('click', () => { history.replaceState({ kx: 1 }, '', '/'); renderLogin(); });
  $('#reset-pw')?.addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
}

function renderSignup() {
  document.body.classList.remove('landing-active');
  document.title = 'Create account · krmax';
  window.onpopstate = () => boot();
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <div class="brand" style="margin-bottom:12px">${brandMark()} Create account</div>
    ${S.pendingInvite
      ? '<p class="task-sub">Accepting an invitation — <b>use the email address it was sent to</b>, or the invite won\'t match.</p>'
      : '<p class="task-sub">You\'ll start in your own personal workspace, ready to create a project. You can be invited into other organizations too.</p>'}
    <div class="form-row"><label>Name</label><input id="signup-name" autocomplete="name" /></div>
    <div class="form-row"><label>Email</label><input type="email" id="signup-email" autocomplete="username" /></div>
    <div class="form-row"><label>Password (10+ characters)</label><input type="password" id="signup-pw" autocomplete="new-password" /></div>
    ${policyAcceptanceMarkup('signup', 'signup-policy-acceptance')}
    <button class="btn primary" id="signup-btn" style="width:100%">Create account</button>
    ${googleBtn('signup-google-btn')}
    ${githubBtn('signup-github-btn')}
    <button class="btn" id="signup-back" style="width:100%;margin-top:8px">Back to sign in</button>
    <div id="signup-err" style="color:var(--danger);font-size:12px;margin-top:8px"></div>
  </div></div>`;
  const go = async () => {
    const name = $('#signup-name').value.trim();
    const email = $('#signup-email').value.trim();
    const password = $('#signup-pw').value;
    let acceptance;
    const invalidEmail = !email || !$('#signup-email').checkValidity();
    const validationError = !name ? 'Enter your name.'
      : invalidEmail ? 'Enter a valid email address.'
        : password.length < 10 ? 'Password must be at least 10 characters.' : '';
    if (validationError) {
      $('#signup-err').textContent = validationError;
      (!name ? $('#signup-name') : invalidEmail ? $('#signup-email') : $('#signup-pw')).focus();
      return;
    }
    try { acceptance = readPolicyAcceptance('signup'); }
    catch (error) { $('#signup-err').textContent = error.message; $('#signup-policy-acceptance').focus(); return; }
    $('#signup-err').textContent = '';
    try {
      const res = await feedbackFetch('/api/signup', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({
        name, email, password, acceptedPolicies: acceptance.accepted, policyVersions: acceptance.versions,
      }) });
      if (res.ok) return boot();
      const body = await res.json().catch(() => ({}));
      // Surface the real reason (Better Auth returns `.message`, e.g. "User already
      // exists") rather than a blanket "Could not create account".
      const reason = body.error || body.message || 'Could not create account';
      const el = $('#signup-err');
      if (/already exists/i.test(reason)) {
        el.innerHTML = `An account with that email already exists. <a href="#" id="signup-to-login" style="color:var(--accent)">Sign in instead</a> — or reset your password.`;
        $('#signup-to-login')?.addEventListener('click', (e) => { e.preventDefault(); renderLogin(); });
      } else {
        el.textContent = reason;
      }
    } catch {
      $('#signup-err').textContent = 'Could not create account. Check your connection and try again.';
    }
  };
  $('#signup-btn').addEventListener('click', go);
  wireSocialBtn('signup-google-btn', 'google', '#signup-err', true);
  wireSocialBtn('signup-github-btn', 'github', '#signup-err', true);
  $('#signup-back').addEventListener('click', () => openPublicAuth('/login', renderLogin));
  $('#signup-pw').addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
}

function renderPolicyCompletion() {
  document.body.classList.remove('landing-active');
  document.title = 'Review policies · krmax';
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <div class="brand" style="margin-bottom:12px">${brandMark()} Finish account setup</div>
    <p class="task-sub">Review and accept the current launch policies before using this paid service.</p>
    ${policyAcceptanceMarkup('signup', 'signup-policy-acceptance')}
    <button class="btn primary" id="complete-policy-acceptance" style="width:100%">Accept and continue</button>
    <div id="policy-completion-err" style="color:var(--danger);font-size:12px;margin-top:8px"></div>
  </div></div>`;
  $('#complete-policy-acceptance').addEventListener('click', async () => {
    try {
      const acceptance = readPolicyAcceptance('signup');
      const response = await feedbackFetch('/api/legal/complete-signup', { method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify(acceptance) });
      if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error || 'Could not record acceptance.');
      await boot();
    } catch (error) { $('#policy-completion-err').textContent = error.message; }
  });
}

function renderAccessPending() {
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <!-- Reached on ANY 403 from /api/projects, not only just after signing up: an
         existing user removed from their last project lands here too, and telling
         them their account was just created is simply false. Describe the state
         (no project access), not a guess about how they got here. -->
    <div class="brand" style="margin-bottom:12px">${brandMark()} No project access</div>
    ${S.inviteNotice ? `<p><b>${esc(S.inviteNotice)}</b></p>` : ''}
    <p>Your account is active, but you're not on any project yet.</p>
    <p class="task-sub">Ask a krmax admin to add you to a project, or create your own organization below. Any new access shows up as soon as you check again.</p>
    <button class="btn primary" id="pending-retry" style="width:100%">Check again</button>
    <button class="btn" id="pending-workspace" style="width:100%;margin-top:8px">Create my own organization</button>
    <button class="btn" id="pending-logout" style="width:100%;margin-top:8px">Sign out</button>
  </div></div>`;
  $('#pending-retry').addEventListener('click', () => boot());
  $('#pending-workspace').addEventListener('click', async () => {
    const organizationName = prompt('Organization name'); if (!organizationName) return;
    const projectName = prompt('First project name', 'My project'); if (!projectName) return;
    try {
      const organization = await api('/api/organizations', { method: 'POST', body: JSON.stringify({ name: organizationName }) });
      await api(`/api/organizations/${organization.id}/projects`, { method: 'POST', body: JSON.stringify({ name: projectName, config: {} }) });
      location.href = '/';
    } catch (error) { toast(error.message, true); }
  });
  $('#pending-logout').addEventListener('click', async () => {
    await feedbackFetch('/api/logout', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' }).catch(() => {});
    location.reload();
  });
}

function renderSetup() {
  $('#app').innerHTML = `<div class="login-wrap"><div class="login-card">
    <div class="brand" style="margin-bottom:12px">${brandMark()} Set up krmax</div>
    <p class="task-sub">Create the first administrator. Additional accounts are managed from Organization settings.</p>
    <div class="form-row"><label>Name</label><input id="setup-name" autocomplete="name" /></div>
    <div class="form-row"><label>Email</label><input type="email" id="setup-email" autocomplete="username" /></div>
    <div class="form-row"><label>Password (10+ characters)</label><input type="password" id="setup-pw" autocomplete="new-password" /></div>
    <button class="btn primary" id="setup-btn" style="width:100%">Create administrator</button>
    <div id="setup-err" style="color:var(--danger);font-size:12px;margin-top:8px"></div>
  </div></div>`;
  const go = async () => {
    const name = $('#setup-name').value.trim();
    const email = $('#setup-email').value.trim();
    const password = $('#setup-pw').value;
    const invalidEmail = !email || !$('#setup-email').checkValidity();
    const validationError = !name ? 'Enter your name.'
      : invalidEmail ? 'Enter a valid email address.'
        : password.length < 10 ? 'Password must be at least 10 characters.' : '';
    if (validationError) {
      $('#setup-err').textContent = validationError;
      (!name ? $('#setup-name') : invalidEmail ? $('#setup-email') : $('#setup-pw')).focus();
      return;
    }
    $('#setup-err').textContent = '';
    try {
      const res = await feedbackFetch('/api/setup', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({
        name, email, password,
      }) });
      if (res.ok) boot();
      else $('#setup-err').textContent = (await res.json().catch(() => ({}))).error || 'Setup failed';
    } catch {
      $('#setup-err').textContent = 'Setup failed. Check your connection and try again.';
    }
  };
  $('#setup-btn').addEventListener('click', go);
  $('#setup-pw').addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
}

boot().catch((e) => { console.error(e); document.getElementById('app').innerHTML = `<div class="empty"><div class="big">Failed to load</div>${esc(e.message)}</div>`; });
